INSERT INTO word_items (id, set_name, set_slug, en, vi, part, topic, note, other_answers, example_en, example_vi, sort_order, course_slug, course_name, course_order, set_order, created_at, updated_at) VALUES
('wn26-01-101', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The lecture will take place at 6:00 P.M., after which attendees may ask questions.', 'Bài giảng sẽ diễn ra lúc 6 giờ chiều, sau đó người tham dự có thể đặt câu hỏi.', 'Part 5', 'Preposition', 'Câu 101 · Đáp án (B) after: after which = sau đó (giới từ + which nối mệnh đề)', 'The lecture will take place at 6:00 PM, after which attendees may ask questions.', NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-102', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The last antique shop in Pepper Valley will close down next month.', 'Cửa hàng đồ cổ cuối cùng ở Pepper Valley sẽ đóng cửa vào tháng sau.', 'Part 5', 'Word form', 'Câu 102 · Đáp án (A) last: the + tính từ last + danh từ', NULL, NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-103', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Merryville residents will receive an online status update about the ongoing bridge construction project.', 'Cư dân Merryville sẽ nhận được bản cập nhật tình hình trực tuyến về dự án xây cầu đang diễn ra.', 'Part 5', 'Vocabulary', 'Câu 103 · Đáp án (A) update: status update = bản cập nhật tình hình', NULL, NULL, NULL, 3, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-104', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'As a result of her many years leading media organizations, Ms. Ayo was selected for the Dowel Journalism Prize.', 'Nhờ nhiều năm lãnh đạo các tổ chức truyền thông của bà, bà Ayo đã được chọn trao Giải Báo chí Dowel.', 'Part 5', 'Pronoun', 'Câu 104 · Đáp án (B) her: tính từ sở hữu her + cụm danh từ many years', 'As a result of her many years leading media organizations, Ms Ayo was selected for the Dowel Journalism Prize.', NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-105', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'To stop the spread of computer viruses, do not open suspicious e-mails.', 'Để ngăn chặn sự lây lan của virus máy tính, đừng mở các e-mail đáng ngờ.', 'Part 5', 'Vocabulary', 'Câu 105 · Đáp án (B) spread: the spread of = sự lây lan của', NULL, NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-106', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The hiring manager carefully considered each applicant''s résumé and qualifications.', 'Người quản lý tuyển dụng đã xem xét cẩn thận hồ sơ và trình độ của từng ứng viên.', 'Part 5', 'Word form', 'Câu 106 · Đáp án (C) carefully: trạng từ đứng trước bổ nghĩa cho động từ considered', NULL, NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-107', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'In October, Mr. Sakamoto will leave for New Zealand and will oversee the opening of the new Auckland branch.', 'Vào tháng Mười, ông Sakamoto sẽ sang New Zealand và sẽ giám sát việc khai trương chi nhánh Auckland mới.', 'Part 5', 'Conjunction', 'Câu 107 · Đáp án (C) and: and nối hai động từ cùng chủ ngữ (will leave … and will oversee)', 'In October, Mr Sakamoto will leave for New Zealand and will oversee the opening of the new Auckland branch.', NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-108', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Tarateer Pharmaceuticals is varying its product line to include over-the-counter medications.', 'Tarateer Pharmaceuticals đang đa dạng hóa dòng sản phẩm để có thêm thuốc không kê đơn.', 'Part 5', 'Word form', 'Câu 108 · Đáp án (D) line: danh từ ghép product line; sau its cần danh từ', NULL, NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-109', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Dynart, Inc., continuously seeks new ways to reduce its use of plastics.', 'Công ty Dynart liên tục tìm kiếm những cách mới để giảm lượng nhựa sử dụng.', 'Part 5', 'Verb form', 'Câu 109 · Đáp án (A) seeks: câu thiếu động từ chính; chủ ngữ số ít → seeks', NULL, NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-110', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The cash registers at Pirkle Books automatically calculate the remaining inventory of books available.', 'Các máy tính tiền ở Pirkle Books tự động tính toán lượng hàng tồn kho còn lại của sách.', 'Part 5', 'Verb form', 'Câu 110 · Đáp án (A) calculate: chủ ngữ số nhiều + trạng từ + động từ chính', NULL, NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-111', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The product team is designing mapping software that can precisely locate underground minerals.', 'Nhóm sản phẩm đang thiết kế phần mềm bản đồ có thể định vị chính xác khoáng sản dưới lòng đất.', 'Part 5', 'Vocabulary', 'Câu 111 · Đáp án (C) precisely: precisely locate = định vị chính xác', NULL, NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-112', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'According to CEO Mayu Yamada, it would not be financially responsible to expand the warehouse at this time.', 'Theo CEO Mayu Yamada, việc mở rộng nhà kho vào lúc này sẽ không khôn ngoan về mặt tài chính.', 'Part 5', 'Word form', 'Câu 112 · Đáp án (C) financially: trạng từ bổ nghĩa cho tính từ responsible', NULL, NULL, NULL, 12, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-113', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Analysts cannot say with any certainty what the regional demand for electric trucks will be.', 'Các nhà phân tích không thể nói một cách chắc chắn nhu cầu xe tải điện trong khu vực sẽ như thế nào.', 'Part 5', 'Vocabulary', 'Câu 113 · Đáp án (A) certainty: with certainty = một cách chắc chắn', NULL, NULL, NULL, 13, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-114', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'As part of its marketing campaign, Elegancia Dishware is actively soliciting feedback from customers.', 'Trong chiến dịch tiếp thị, Elegancia Dishware đang tích cực thu thập ý kiến phản hồi từ khách hàng.', 'Part 5', 'Vocabulary', 'Câu 114 · Đáp án (C) actively: actively + V-ing = tích cực làm gì', NULL, NULL, NULL, 14, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-115', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Rain gardens are intended to absorb water to prevent flooding of local roads.', 'Vườn mưa được thiết kế để hấp thụ nước nhằm ngăn ngập úng các con đường địa phương.', 'Part 5', 'Vocabulary', 'Câu 115 · Đáp án (C) absorb: absorb water = hấp thụ nước', NULL, NULL, NULL, 15, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-116', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Theta Industries'' training program aims to increase the productivity of its manufacturing systems.', 'Chương trình đào tạo của Theta Industries nhằm tăng năng suất của các hệ thống sản xuất.', 'Part 5', 'Word form', 'Câu 116 · Đáp án (D) productivity: the + danh từ + of', NULL, NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-117', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The board of directors has voted to award Mr. Mitrakos a bonus for his role in obtaining the international contract.', 'Hội đồng quản trị đã biểu quyết thưởng cho ông Mitrakos vì vai trò của ông trong việc giành được hợp đồng quốc tế.', 'Part 5', 'Preposition', 'Câu 117 · Đáp án (A) in: role in + V-ing = vai trò trong việc', 'The board of directors has voted to award Mr Mitrakos a bonus for his role in obtaining the international contract.', NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-118', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The finance director gave his approval so that the project can move forward.', 'Giám đốc tài chính đã phê duyệt để dự án có thể tiến hành.', 'Part 5', 'Conjunction', 'Câu 118 · Đáp án (D) so that: so that + S + can = để (chỉ mục đích)', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-119', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The newspaper article describes ways job seekers can compensate for having little workplace experience.', 'Bài báo mô tả những cách người tìm việc có thể bù đắp cho việc có ít kinh nghiệm làm việc.', 'Part 5', 'Vocabulary', 'Câu 119 · Đáp án (C) compensate: compensate for = bù đắp cho', NULL, NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-120', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Mr. Ellis and Ms. Barnes were both highly qualified, but neither got the job.', 'Ông Ellis và bà Barnes đều rất có năng lực, nhưng không ai trong hai người nhận được công việc.', 'Part 5', 'Pronoun', 'Câu 120 · Đáp án (B) neither: neither = không ai trong hai (người)', 'Mr Ellis and Ms Barnes were both highly qualified, but neither got the job.', NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-121', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Ennis Photography purchased all new lighting equipment despite the high cost.', 'Ennis Photography đã mua toàn bộ thiết bị chiếu sáng mới bất chấp chi phí cao.', 'Part 5', 'Preposition', 'Câu 121 · Đáp án (D) despite: despite + danh từ; even though + mệnh đề', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-122', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Marburton residents who wish to sell a home should contact the award-winning team at Kwan Real Estate.', 'Cư dân Marburton muốn bán nhà nên liên hệ đội ngũ từng đoạt giải của Kwan Real Estate.', 'Part 5', 'Verb form', 'Câu 122 · Đáp án (C) sell: wish to + V nguyên mẫu', NULL, NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-123', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Maswa Bistro began a cooperative agreement with local farmers to purchase a set amount of produce each week.', 'Maswa Bistro đã bắt đầu một thỏa thuận hợp tác với nông dân địa phương để mua một lượng nông sản cố định mỗi tuần.', 'Part 5', 'Vocabulary', 'Câu 123 · Đáp án (B) cooperative: cooperative agreement = thỏa thuận hợp tác', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-124', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The City of Doyle''s new downtown parking restrictions have been met with opposition by residents and visitors.', 'Các quy định hạn chế đỗ xe mới ở trung tâm thành phố Doyle đã vấp phải sự phản đối của cư dân và du khách.', 'Part 5', 'Word form', 'Câu 124 · Đáp án (C) restrictions: cần danh từ số nhiều làm chủ ngữ cho have been', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-125', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The plumbing position requires extensive training, even for those who studied diligently in technical school.', 'Vị trí thợ sửa ống nước đòi hỏi đào tạo chuyên sâu, ngay cả với những người đã học tập chăm chỉ ở trường kỹ thuật.', 'Part 5', 'Vocabulary', 'Câu 125 · Đáp án (A) diligently: study diligently = học chăm chỉ', NULL, NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-126', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'With its fixed price assurance, Omega Cellular guarantees no phone bill increases for three years.', 'Với cam kết giá cố định, Omega Cellular đảm bảo hóa đơn điện thoại không tăng trong ba năm.', 'Part 5', 'Word form', 'Câu 126 · Đáp án (A) assurance: its + cụm danh từ → cần danh từ assurance', NULL, NULL, NULL, 26, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-127', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'As chief analytics officer, Mr. Ko has worked at Lochston Ltd. with great dedication for more than twenty years.', 'Với vai trò giám đốc phân tích, ông Ko đã làm việc tại Lochston Ltd. với sự tận tâm lớn trong hơn hai mươi năm.', 'Part 5', 'Vocabulary', 'Câu 127 · Đáp án (D) dedication: with dedication = với sự tận tâm', 'As chief analytics officer, Mr Ko has worked at Lochston Ltd. with great dedication for more than twenty years.', NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-128', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'Milltown Hospital''s cafeteria serves lunch seven days a week rather than only on weekdays.', 'Căng tin của Bệnh viện Milltown phục vụ bữa trưa bảy ngày một tuần thay vì chỉ vào các ngày trong tuần.', 'Part 5', 'Conjunction', 'Câu 128 · Đáp án (D) rather than: rather than = thay vì', NULL, NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-129', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'The store''s entire inventory of lumber comes from a nearby commercial supplier.', 'Toàn bộ gỗ xẻ trong kho của cửa hàng đến từ một nhà cung cấp thương mại gần đó.', 'Part 5', 'Vocabulary', 'Câu 129 · Đáp án (D) commercial: commercial supplier = nhà cung cấp thương mại', NULL, NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-01-130', 'ETS 2026 · Test 01', 'winner-e26-p5-01', 'For a $95 diagnostic fee, our mechanics will determine what repairs are needed.', 'Với phí chẩn đoán 95 đô la, thợ máy của chúng tôi sẽ xác định cần sửa chữa những gì.', 'Part 5', 'Word form', 'Câu 130 · Đáp án (B) diagnostic: tính từ diagnostic bổ nghĩa cho danh từ fee', NULL, NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 1, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-101', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The all-new Amore sports sedan is engineered for maximum reliability and gas mileage.', 'Mẫu sedan thể thao Amore hoàn toàn mới được thiết kế để đạt độ tin cậy và mức tiết kiệm nhiên liệu tối đa.', 'Part 5', 'Conjunction', 'Câu 101 · Đáp án (C) and: and nối hai danh từ ngang hàng', NULL, NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-102', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The staff was grateful for the information that Mr. Schuller distributed at the meeting.', 'Nhân viên biết ơn vì thông tin mà ông Schuller đã phát tại cuộc họp.', 'Part 5', 'Word form', 'Câu 102 · Đáp án (A) information: the + danh từ information', 'The staff was grateful for the information that Mr Schuller distributed at the meeting.', NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-103', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The next meeting of the planning committee will be held promptly at 2 P.M.', 'Cuộc họp tiếp theo của ủy ban kế hoạch sẽ được tổ chức đúng 2 giờ chiều.', 'Part 5', 'Vocabulary', 'Câu 103 · Đáp án (D) promptly: promptly at + giờ = đúng giờ', 'The next meeting of the planning committee will be held promptly at 2 PM', NULL, NULL, 3, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-104', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Reimbursement for travel expenses will be included in your October 1 paycheck.', 'Khoản hoàn trả chi phí đi lại sẽ được đưa vào phiếu lương ngày 1 tháng 10 của bạn.', 'Part 5', 'Pronoun', 'Câu 104 · Đáp án (B) your: tính từ sở hữu your + cụm danh từ', NULL, NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-105', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The lead design engineer on the drone camera project is Iseul Bae.', 'Kỹ sư thiết kế chính của dự án camera drone là Iseul Bae.', 'Part 5', 'Vocabulary', 'Câu 105 · Đáp án (A) lead: lead (tính từ) = chính, trưởng', NULL, NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-106', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'After reading several reviews, Mr. Kim was able to decide which printer to buy for the office.', 'Sau khi đọc vài bài đánh giá, ông Kim đã quyết định được nên mua máy in nào cho văn phòng.', 'Part 5', 'Verb form', 'Câu 106 · Đáp án (D) to buy: từ để hỏi (which + N) + to V', 'After reading several reviews, Mr Kim was able to decide which printer to buy for the office.', NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-107', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Please remove the boxes left in the staff lounge by 5 P.M.', 'Vui lòng dọn các thùng để trong phòng nghỉ nhân viên trước 5 giờ chiều.', 'Part 5', 'Preposition', 'Câu 107 · Đáp án (D) by: by + mốc thời gian = chậm nhất là, trước', 'Please remove the boxes left in the staff lounge by 5 PM', NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-108', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The Southport manufacturing plant is expected to begin production in three days.', 'Nhà máy sản xuất Southport dự kiến bắt đầu sản xuất trong ba ngày tới.', 'Part 5', 'Word form', 'Câu 108 · Đáp án (C) manufacturing: danh từ ghép manufacturing plant', NULL, NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-109', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'After accepting a job offer, a candidate must complete all onboarding tasks before the start date.', 'Sau khi nhận lời mời làm việc, ứng viên phải hoàn thành mọi thủ tục nhập việc trước ngày bắt đầu.', 'Part 5', 'Vocabulary', 'Câu 109 · Đáp án (A) complete: complete tasks = hoàn thành nhiệm vụ', NULL, NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-110', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Although her training has just begun, Ms. Yu has already mastered the company''s proprietary accounting software.', 'Mặc dù khóa đào tạo của cô ấy vừa mới bắt đầu, cô Yu đã thành thạo phần mềm kế toán độc quyền của công ty.', 'Part 5', 'Pronoun', 'Câu 110 · Đáp án (A) her: tính từ sở hữu her + danh từ training', 'Although her training has just begun, Ms Yu has already mastered the company''s proprietary accounting software.', NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-111', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Ms. Clayton was relieved to find that none of her files had been lost during the power failure.', 'Cô Clayton nhẹ nhõm khi thấy không tập tin nào của mình bị mất trong lúc mất điện.', 'Part 5', 'Vocabulary', 'Câu 111 · Đáp án (C) relieved: be relieved to V = nhẹ nhõm khi', 'Ms Clayton was relieved to find that none of her files had been lost during the power failure.', NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-112', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'During Mr. Nagahori''s tenure as CEO at Unten Properties, the company has grown significantly.', 'Trong nhiệm kỳ CEO của ông Nagahori tại Unten Properties, công ty đã phát triển đáng kể.', 'Part 5', 'Word form', 'Câu 112 · Đáp án (D) significantly: trạng từ bổ nghĩa cho động từ grow', 'During Mr Nagahori''s tenure as CEO at Unten Properties, the company has grown significantly.', NULL, NULL, 12, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-113', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Safety must always be the top priority in each step of the glassblowing process.', 'An toàn phải luôn là ưu tiên hàng đầu trong mỗi bước của quy trình thổi thủy tinh.', 'Part 5', 'Vocabulary', 'Câu 113 · Đáp án (C) priority: top priority = ưu tiên hàng đầu', NULL, NULL, NULL, 13, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-114', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Central Science Museum hosts online seminars by experts who cover topics related to information technology.', 'Bảo tàng Khoa học Trung tâm tổ chức hội thảo trực tuyến của các chuyên gia đề cập các chủ đề liên quan đến công nghệ thông tin.', 'Part 5', 'Verb form', 'Câu 114 · Đáp án (D) cover: who thay cho experts (số nhiều) → cover, chủ động', NULL, NULL, NULL, 14, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-115', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Conradia Computers abruptly changed the direction of its marketing strategy last week.', 'Conradia Computers đã đột ngột thay đổi định hướng chiến lược tiếp thị vào tuần trước.', 'Part 5', 'Vocabulary', 'Câu 115 · Đáp án (B) abruptly: abruptly = đột ngột', NULL, NULL, NULL, 15, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-116', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Because of an abundance of qualified candidates, Xaniper Industries may take longer than expected to name a new CEO.', 'Vì có rất nhiều ứng viên đủ năng lực, Xaniper Industries có thể mất nhiều thời gian hơn dự kiến để bổ nhiệm CEO mới.', 'Part 5', 'Word form', 'Câu 116 · Đáp án (C) qualified: tính từ qualified + danh từ candidates', NULL, NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-117', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'All of our tablet computers come with a one-year warranty that includes hardware repairs and replacements.', 'Tất cả máy tính bảng của chúng tôi đều kèm bảo hành một năm bao gồm sửa chữa và thay thế phần cứng.', 'Part 5', 'Pronoun', 'Câu 117 · Đáp án (A) that: đại từ quan hệ that thay cho vật (warranty)', NULL, NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-118', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The Exprite Foundation Board of Directors is composed of nine members who are elected annually by the public.', 'Hội đồng quản trị Quỹ Exprite gồm có chín thành viên được công chúng bầu hằng năm.', 'Part 5', 'Vocabulary', 'Câu 118 · Đáp án (C) composed: be composed of = gồm có', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-119', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Mortgage brokers generally prefer to review all the financial documents before meeting with a new client.', 'Các nhà môi giới thế chấp thường muốn xem xét toàn bộ hồ sơ tài chính trước khi gặp khách hàng mới.', 'Part 5', 'Preposition', 'Câu 119 · Đáp án (D) before: before + V-ing = trước khi', NULL, NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-120', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Management will identify candidates for promotion by the end of the month.', 'Ban quản lý sẽ xác định các ứng viên được thăng chức trước cuối tháng.', 'Part 5', 'Verb form', 'Câu 120 · Đáp án (C) will identify: by the end of the month → thì tương lai', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-121', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'While we typically charge $25 for missed appointments, we understand that unforeseen circumstances may arise.', 'Dù thường thu 25 đô la cho các cuộc hẹn bị lỡ, chúng tôi hiểu rằng những tình huống bất ngờ có thể xảy ra.', 'Part 5', 'Vocabulary', 'Câu 121 · Đáp án (A) unforeseen: unforeseen circumstances = tình huống không lường trước', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-122', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'At Blu Hedge, clients receive 1 percent interest, pay no account fees, and can make unlimited transfers.', 'Tại Blu Hedge, khách hàng nhận lãi suất 1%, không trả phí tài khoản và có thể chuyển khoản không giới hạn.', 'Part 5', 'Word form', 'Câu 122 · Đáp án (B) transfers: unlimited + danh từ đếm được số nhiều', NULL, NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-123', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Farist Bakery, which specializes in dessert catering, is located near the Liverpool Convention Complex.', 'Tiệm bánh Farist, chuyên cung cấp món tráng miệng cho tiệc, nằm gần Khu Hội nghị Liverpool.', 'Part 5', 'Preposition', 'Câu 123 · Đáp án (A) near: be located near = nằm gần', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-124', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The presentations were briefer than we expected, so there was ample time left for questions.', 'Các bài thuyết trình ngắn hơn chúng tôi dự kiến, nên còn nhiều thời gian cho phần hỏi đáp.', 'Part 5', 'Word form', 'Câu 124 · Đáp án (C) briefer: so sánh hơn + than', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-125', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'According to our guarantee, your order will arrive in three days or we will refund 50 percent of the cost.', 'Theo cam kết của chúng tôi, đơn hàng sẽ đến trong ba ngày, nếu không chúng tôi sẽ hoàn lại 50% chi phí.', 'Part 5', 'Vocabulary', 'Câu 125 · Đáp án (B) guarantee: guarantee = sự cam kết, bảo đảm', NULL, NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-126', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Several Seoul-based companies have notably redesigned their workplaces to be more colorful and comfortable.', 'Một số công ty có trụ sở tại Seoul đã thiết kế lại một cách đáng chú ý nơi làm việc để nhiều màu sắc và thoải mái hơn.', 'Part 5', 'Word form', 'Câu 126 · Đáp án (D) notably: trạng từ đứng giữa have và V3', NULL, NULL, NULL, 26, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-127', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The employee picnic will be postponed until next Friday because of the unseasonably cold temperatures this week.', 'Buổi dã ngoại của nhân viên sẽ hoãn đến thứ Sáu tới vì nhiệt độ lạnh bất thường so với mùa trong tuần này.', 'Part 5', 'Vocabulary', 'Câu 127 · Đáp án (D) unseasonably: unseasonably = bất thường so với mùa', NULL, NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-128', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'The accounting department is in first place in the office fund-raising challenge, with just two more days to go.', 'Phòng kế toán đang dẫn đầu cuộc thi gây quỹ của văn phòng, khi chỉ còn hai ngày nữa.', 'Part 5', 'Preposition', 'Câu 128 · Đáp án (C) with: with + N + to go = khi còn …', NULL, NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-129', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Pink Geranium Coffee has struggled to distinguish its new bottled espresso from similar beverages on the market.', 'Pink Geranium Coffee đã chật vật để tạo sự khác biệt cho cà phê espresso đóng chai mới so với các đồ uống tương tự trên thị trường.', 'Part 5', 'Vocabulary', 'Câu 129 · Đáp án (B) distinguish: distinguish A from B = phân biệt A với B', NULL, NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-02-130', 'ETS 2026 · Test 02', 'winner-e26-p5-02', 'Though it is occasionally inconvenient, Mr. Ohtani expects all team members to attend his weekly meeting.', 'Dù đôi khi bất tiện, ông Ohtani vẫn yêu cầu tất cả thành viên nhóm tham dự cuộc họp hằng tuần.', 'Part 5', 'Conjunction', 'Câu 130 · Đáp án (A) Though: Though + mệnh đề = mặc dù', 'Though it is occasionally inconvenient, Mr Ohtani expects all team members to attend his weekly meeting.', NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 2, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-101', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Despite her youth, Ms. Cho is already quite popular on social media.', 'Mặc dù tuổi còn trẻ, cô Cho đã khá nổi tiếng trên mạng xã hội.', 'Part 5', 'Pronoun', 'Câu 101 · Đáp án (B) her: tính từ sở hữu her + danh từ youth', 'Despite her youth, Ms Cho is already quite popular on social media.', NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-102', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Most of the materials distributed at last month''s accounting conference are now available online.', 'Hầu hết tài liệu phát tại hội nghị kế toán tháng trước hiện đã có sẵn trên mạng.', 'Part 5', 'Vocabulary', 'Câu 102 · Đáp án (A) available: available online = có sẵn trên mạng', NULL, NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
