('wn26-03-104', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Poshy Shoes vice president Lucille Jeris has been promoted to president of the company.', 'Phó chủ tịch Poshy Shoes Lucille Jeris đã được thăng chức lên chủ tịch công ty.', 'Part 5', 'Vocabulary', 'Câu 104 · Đáp án (C) promoted: be promoted to = được thăng chức lên', NULL, NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-105', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'The report found that employees who take regular breaks are more productive than those who take no breaks.', 'Báo cáo cho thấy nhân viên nghỉ giải lao đều đặn làm việc hiệu quả hơn những người không nghỉ.', 'Part 5', 'Word form', 'Câu 105 · Đáp án (D) productive: be + more + tính từ + than', NULL, NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-106', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Customers of Twins Photocopiers are encouraged to contact a technician if their machines need repairs.', 'Khách hàng của Twins Photocopiers được khuyến khích liên hệ với kỹ thuật viên nếu máy cần sửa chữa.', 'Part 5', 'Vocabulary', 'Câu 106 · Đáp án (B) technician: technician = kỹ thuật viên', NULL, NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-107', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'The heavy traffic on the way to the airport nearly caused Ms. Ikeda to miss her flight.', 'Giao thông đông đúc trên đường ra sân bay suýt khiến cô Ikeda lỡ chuyến bay.', 'Part 5', 'Word form', 'Câu 107 · Đáp án (A) nearly: trạng từ nearly bổ nghĩa cho động từ caused', 'The heavy traffic on the way to the airport nearly caused Ms Ikeda to miss her flight.', NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-108', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'A news source suggested that the merger will probably take place next year.', 'Một nguồn tin cho biết vụ sáp nhập có lẽ sẽ diễn ra vào năm sau.', 'Part 5', 'Vocabulary', 'Câu 108 · Đáp án (B) probably: probably = có lẽ', NULL, NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-109', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'The Seaborne Inn has various beautiful guest rooms that can be booked on a monthly basis.', 'Seaborne Inn có nhiều phòng nghỉ đẹp khác nhau có thể đặt theo tháng.', 'Part 5', 'Vocabulary', 'Câu 109 · Đáp án (A) various: various + danh từ số nhiều', NULL, NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-110', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Ahearn Accessories'' retail shop is located at Gordon Avenue and Hutch Street.', 'Cửa hàng bán lẻ của Ahearn Accessories nằm ở góc đại lộ Gordon và phố Hutch.', 'Part 5', 'Preposition', 'Câu 110 · Đáp án (C) at: at + giao lộ hai con đường', NULL, NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-111', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'A majority of the city''s residents rated its transportation app as acceptable.', 'Đa số cư dân thành phố đánh giá ứng dụng giao thông là chấp nhận được.', 'Part 5', 'Word form', 'Câu 111 · Đáp án (B) acceptable: rate + O + as + tính từ', NULL, NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-112', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Dr. Cheung is representing Silk Valley Hospital at next weekend''s medical fair.', 'Bác sĩ Cheung sẽ đại diện cho Bệnh viện Silk Valley tại hội chợ y tế cuối tuần sau.', 'Part 5', 'Verb form', 'Câu 112 · Đáp án (C) is representing: hiện tại tiếp diễn diễn tả kế hoạch tương lai (next weekend)', 'Dr Cheung is representing Silk Valley Hospital at next weekend''s medical fair.', NULL, NULL, 12, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-113', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Frankie''s Boutique had a financially profitable quarter after taking measures to reduce costs.', 'Frankie''s Boutique đã có một quý có lãi về mặt tài chính sau khi áp dụng các biện pháp cắt giảm chi phí.', 'Part 5', 'Vocabulary', 'Câu 113 · Đáp án (B) profitable: profitable = có lãi', NULL, NULL, NULL, 13, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-114', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Because it submitted the lowest bid, Deb''s Gifting has been chosen as the supplier of this year''s holiday cards.', 'Vì gửi giá thầu thấp nhất, Deb''s Gifting đã được chọn làm nhà cung cấp thiệp lễ năm nay.', 'Part 5', 'Word form', 'Câu 114 · Đáp án (B) supplier: danh từ chỉ người (công ty) supplier', NULL, NULL, NULL, 14, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-115', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'The Whitetail Institute is the only organization that tracks deer populations in rapidly expanding suburban areas.', 'Viện Whitetail là tổ chức duy nhất theo dõi quần thể hươu ở các vùng ngoại ô đang mở rộng nhanh chóng.', 'Part 5', 'Vocabulary', 'Câu 115 · Đáp án (D) organization: Institute = organization (tổ chức)', NULL, NULL, NULL, 15, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-116', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'The committee members who attended the meeting are listed in the appendix.', 'Các thành viên ủy ban đã tham dự cuộc họp được liệt kê trong phụ lục.', 'Part 5', 'Pronoun', 'Câu 116 · Đáp án (A) who: đại từ quan hệ who thay cho người', NULL, NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-117', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Our new app is specifically designed to provide data-driven insights to investment professionals.', 'Ứng dụng mới của chúng tôi được thiết kế riêng để cung cấp thông tin phân tích dựa trên dữ liệu cho các chuyên gia đầu tư.', 'Part 5', 'Word form', 'Câu 117 · Đáp án (D) specifically: trạng từ đứng giữa be và V3', NULL, NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-118', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'The results of the study suggest that more people struggle with night driving than previously believed.', 'Kết quả nghiên cứu cho thấy có nhiều người gặp khó khăn khi lái xe ban đêm hơn so với suy nghĩ trước đây.', 'Part 5', 'Verb form', 'Câu 118 · Đáp án (D) struggle: chủ ngữ số nhiều people → struggle', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-119', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Each department has been asked to develop an action plan in response to the budget cuts announced last week.', 'Mỗi phòng ban được yêu cầu xây dựng kế hoạch hành động để ứng phó với việc cắt giảm ngân sách được công bố tuần trước.', 'Part 5', 'Vocabulary', 'Câu 119 · Đáp án (A) response: in response to = để đáp lại, ứng phó với', NULL, NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-120', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Our popular online training materials have consistently been shown to improve job seekers'' skills.', 'Tài liệu đào tạo trực tuyến phổ biến của chúng tôi đã liên tục được chứng minh là giúp cải thiện kỹ năng của người tìm việc.', 'Part 5', 'Vocabulary', 'Câu 120 · Đáp án (A) consistently: consistently = một cách nhất quán, liên tục', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-121', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Ms. Yamada, former director of the Midlands Chamber of Commerce, was recently appointed to the state trade commission.', 'Bà Yamada, cựu giám đốc Phòng Thương mại Midlands, vừa được bổ nhiệm vào ủy ban thương mại bang.', 'Part 5', 'Word form', 'Câu 121 · Đáp án (B) former: tính từ former + danh từ director', 'Ms Yamada, former director of the Midlands Chamber of Commerce, was recently appointed to the state trade commission.', NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-122', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'The software uses computer memory efficiently, allowing users to open up to five files simultaneously.', 'Phần mềm sử dụng bộ nhớ máy tính hiệu quả, cho phép người dùng mở tối đa năm tập tin cùng lúc.', 'Part 5', 'Preposition', 'Câu 122 · Đáp án (C) up to: up to + số lượng = tối đa', NULL, NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-123', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'A monthly newsletter is an excellent way to promote your group''s activities and events.', 'Bản tin hằng tháng là cách tuyệt vời để quảng bá các hoạt động và sự kiện của nhóm bạn.', 'Part 5', 'Vocabulary', 'Câu 123 · Đáp án (D) promote: promote = quảng bá', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-124', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'While the hotel does not have a restaurant on site, there are many dining options nearby.', 'Dù khách sạn không có nhà hàng tại chỗ, gần đó có nhiều lựa chọn ăn uống.', 'Part 5', 'Conjunction', 'Câu 124 · Đáp án (A) While: While + mệnh đề = mặc dù', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-125', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Despite a slight decline in revenue from the previous quarter, Blakely Components is moving forward with its expansion plan.', 'Bất chấp doanh thu giảm nhẹ so với quý trước, Blakely Components vẫn tiếp tục kế hoạch mở rộng.', 'Part 5', 'Preposition', 'Câu 125 · Đáp án (B) Despite: Despite + cụm danh từ', NULL, NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-126', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Abelia Dairy Company has undergone several changes in leadership over the past ten years.', 'Công ty Sữa Abelia đã trải qua nhiều lần thay đổi lãnh đạo trong mười năm qua.', 'Part 5', 'Preposition', 'Câu 126 · Đáp án (A) over: over the past + thời gian (+ hiện tại hoàn thành)', NULL, NULL, NULL, 26, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-127', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Opal City''s Community Theater is holding auditions for its spring production during the first week of December.', 'Nhà hát Cộng đồng Opal City đang tổ chức buổi thử vai cho vở diễn mùa xuân vào tuần đầu tháng Mười Hai.', 'Part 5', 'Word form', 'Câu 127 · Đáp án (C) auditions: hold + danh từ auditions', NULL, NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-128', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Mr. Kane said he packed so hastily this morning that he forgot to bring a suit and tie for tomorrow''s dinner.', 'Ông Kane nói sáng nay ông soạn đồ vội vàng đến mức quên mang bộ vest và cà vạt cho bữa tối ngày mai.', 'Part 5', 'Vocabulary', 'Câu 128 · Đáp án (C) hastily: so + trạng từ + that = … đến mức', 'Mr Kane said he packed so hastily this morning that he forgot to bring a suit and tie for tomorrow''s dinner.', NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-129', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Long before the training program began, Ms. Morris had revised the schedule to allow her team to attend.', 'Rất lâu trước khi chương trình đào tạo bắt đầu, cô Morris đã điều chỉnh lịch trình để nhóm của cô có thể tham dự.', 'Part 5', 'Verb form', 'Câu 129 · Đáp án (C) had revised: quá khứ hoàn thành: xảy ra trước mốc quá khứ (began)', 'Long before the training program began, Ms Morris had revised the schedule to allow her team to attend.', NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-03-130', 'ETS 2026 · Test 03', 'winner-e26-p5-03', 'Mr. Swan will return to the planning meeting once the interns have arrived.', 'Ông Swan sẽ quay lại cuộc họp lập kế hoạch khi các thực tập sinh đã đến.', 'Part 5', 'Conjunction', 'Câu 130 · Đáp án (A) once: once + mệnh đề = một khi, khi', 'Mr Swan will return to the planning meeting once the interns have arrived.', NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 3, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-101', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Ms. Chiu recently announced that she is planning to retire in September.', 'Bà Chiu vừa thông báo rằng bà ấy dự định nghỉ hưu vào tháng Chín.', 'Part 5', 'Pronoun', 'Câu 101 · Đáp án (D) she: cần đại từ chủ ngữ cho động từ is planning', 'Ms Chiu recently announced that she is planning to retire in September.', NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-102', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Mr. Kashnitz will interview the applicants before the holiday.', 'Ông Kashnitz sẽ phỏng vấn các ứng viên trước kỳ nghỉ lễ.', 'Part 5', 'Preposition', 'Câu 102 · Đáp án (B) before: before + mốc thời gian', 'Mr Kashnitz will interview the applicants before the holiday.', NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-103', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'The real estate agent may provide a buyer with a neighborhood analysis upon request.', 'Nhân viên bất động sản có thể cung cấp cho người mua bản phân tích khu dân cư khi được yêu cầu.', 'Part 5', 'Verb form', 'Câu 103 · Đáp án (B) provide: may + V nguyên mẫu; provide sb with sth', NULL, NULL, NULL, 3, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-104', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'The city''s development committee is looking for a location to plant a community garden.', 'Ủy ban phát triển của thành phố đang tìm một địa điểm để trồng vườn cộng đồng.', 'Part 5', 'Vocabulary', 'Câu 104 · Đáp án (C) location: location = địa điểm', NULL, NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-105', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'We hope our customer service team has answered your questions in a satisfactory manner.', 'Chúng tôi hy vọng đội chăm sóc khách hàng đã trả lời câu hỏi của bạn một cách thỏa đáng.', 'Part 5', 'Word form', 'Câu 105 · Đáp án (B) satisfactory: a + tính từ + danh từ manner', NULL, NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-106', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Mr. Hanley expressed interest in the position previously held by Ms. Akello.', 'Ông Hanley bày tỏ sự quan tâm đến vị trí trước đây do bà Akello đảm nhận.', 'Part 5', 'Vocabulary', 'Câu 106 · Đáp án (A) previously: previously held = trước đây đảm nhận', 'Mr Hanley expressed interest in the position previously held by Ms Akello.', NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-107', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Once Ms. Jeong receives the contract, she will sign and return it to Allory Pharmaceuticals.', 'Khi cô Jeong nhận được hợp đồng, cô ấy sẽ ký và gửi lại cho Allory Pharmaceuticals.', 'Part 5', 'Verb form', 'Câu 107 · Đáp án (B) receives: mệnh đề thời gian (once) dùng hiện tại đơn cho tương lai', 'Once Ms Jeong receives the contract, she will sign and return it to Allory Pharmaceuticals.', NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-108', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Ten board members plan to attend, which is just enough to approve the proposal.', 'Mười thành viên hội đồng dự định tham dự, vừa đủ để thông qua đề xuất.', 'Part 5', 'Word form', 'Câu 108 · Đáp án (A) enough: enough to V = đủ để', NULL, NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-109', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Mr. Aziz is often alone in the shop while his partner is out making a delivery.', 'Ông Aziz thường ở một mình trong cửa hàng khi cộng sự của ông ra ngoài đi giao hàng.', 'Part 5', 'Word form', 'Câu 109 · Đáp án (B) delivery: make a delivery = giao hàng; a + danh từ', 'Mr Aziz is often alone in the shop while his partner is out making a delivery.', NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-110', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'The Pacific Coast Sunset Run has been rescheduled to August 31 because of bad weather.', 'Giải chạy Pacific Coast Sunset đã được dời lịch sang ngày 31 tháng 8 vì thời tiết xấu.', 'Part 5', 'Vocabulary', 'Câu 110 · Đáp án (C) rescheduled: reschedule to + ngày = dời sang', NULL, NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-111', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Graber hair and nail growth supplements come in both pill and liquid form.', 'Thực phẩm bổ sung giúp mọc tóc và móng Graber có cả dạng viên và dạng lỏng.', 'Part 5', 'Conjunction', 'Câu 111 · Đáp án (B) both: both A and B = cả A và B', NULL, NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-112', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'The posters must be completed soon so that they can be put up in advance of the gala.', 'Các áp phích phải được hoàn thành sớm để có thể treo lên trước buổi dạ tiệc.', 'Part 5', 'Conjunction', 'Câu 112 · Đáp án (A) so that: so that + S + can = để', NULL, NULL, NULL, 12, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-113', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Mr. Olivero praised the film in his review, even though he personally disliked its aesthetic style.', 'Ông Olivero khen bộ phim trong bài đánh giá, dù cá nhân ông không thích phong cách thẩm mỹ của nó.', 'Part 5', 'Word form', 'Câu 113 · Đáp án (B) personally: trạng từ bổ nghĩa cho động từ disliked', 'Mr Olivero praised the film in his review, even though he personally disliked its aesthetic style.', NULL, NULL, 13, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-114', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'After weeks of record-setting rain, expect only blue skies this weekend.', 'Sau nhiều tuần mưa kỷ lục, cuối tuần này trời sẽ chỉ toàn trong xanh.', 'Part 5', 'Preposition', 'Câu 114 · Đáp án (A) After: After + cụm danh từ = sau', NULL, NULL, NULL, 14, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-115', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'The Serenica dining table comes with levelers to ensure its stability on uneven surfaces.', 'Bàn ăn Serenica đi kèm chân chỉnh cân bằng để đảm bảo độ vững chắc trên bề mặt không bằng phẳng.', 'Part 5', 'Verb form', 'Câu 115 · Đáp án (C) to ensure: to V chỉ mục đích', NULL, NULL, NULL, 15, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-116', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Applicants to any open position at Allcrest Engineering can expect a response within three business days.', 'Ứng viên cho bất kỳ vị trí nào đang tuyển tại Allcrest Engineering có thể nhận được phản hồi trong vòng ba ngày làm việc.', 'Part 5', 'Vocabulary', 'Câu 116 · Đáp án (D) response: expect a response = chờ nhận phản hồi', NULL, NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-117', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Whoever prepares the patient''s medical records is required to maintain confidentiality.', 'Bất kỳ ai chuẩn bị hồ sơ y tế của bệnh nhân đều phải giữ bí mật.', 'Part 5', 'Pronoun', 'Câu 117 · Đáp án (A) Whoever: Whoever = bất kỳ ai; làm chủ ngữ cho cả hai động từ', NULL, NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-118', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Because of the high demand for our services, our office was significantly expanded last year.', 'Do nhu cầu cao đối với dịch vụ của chúng tôi, văn phòng đã được mở rộng đáng kể vào năm ngoái.', 'Part 5', 'Vocabulary', 'Câu 118 · Đáp án (A) significantly: significantly = đáng kể', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-119', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'The Terry Hoig Prize for sustainable architecture was awarded to Ms. Helblon on Tuesday.', 'Giải thưởng Terry Hoig về kiến trúc bền vững đã được trao cho bà Helblon vào thứ Ba.', 'Part 5', 'Word form', 'Câu 119 · Đáp án (B) sustainable: tính từ sustainable + danh từ architecture', 'The Terry Hoig Prize for sustainable architecture was awarded to Ms Helblon on Tuesday.', NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-120', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'We have been experiencing problems with the thermostat in the western end of the warehouse.', 'Chúng tôi liên tục gặp sự cố với bộ điều nhiệt ở khu phía tây nhà kho.', 'Part 5', 'Vocabulary', 'Câu 120 · Đáp án (A) experiencing: experience problems = gặp sự cố', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-121', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Two students from Wrisley University worked collaboratively on the design of the new library in Lorth Park.', 'Hai sinh viên Đại học Wrisley đã làm việc cùng nhau để thiết kế thư viện mới ở Lorth Park.', 'Part 5', 'Word form', 'Câu 121 · Đáp án (C) collaboratively: trạng từ bổ nghĩa cho động từ worked', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-122', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'The images displayed on our gallery''s Web site may not reflect the exact colors of the artwork for sale.', 'Hình ảnh hiển thị trên trang web của phòng tranh có thể không phản ánh màu sắc chính xác của tác phẩm đang bán.', 'Part 5', 'Vocabulary', 'Câu 122 · Đáp án (D) exact: exact = chính xác', 'The images displayed on our gallery''s Website may not reflect the exact colors of the artwork for sale.', NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-123', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'At Beautyvale Cosmetics, our representatives answer customers'' inquiries within 24 hours of receipt.', 'Tại Beautyvale Cosmetics, nhân viên của chúng tôi trả lời các thắc mắc của khách hàng trong vòng 24 giờ kể từ khi nhận.', 'Part 5', 'Word form', 'Câu 123 · Đáp án (D) inquiries: sở hữu cách + danh từ inquiries', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-124', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'We would like to attend the retreat, but regrettably we are unavailable on that date.', 'Chúng tôi muốn tham dự chuyến nghỉ dưỡng, nhưng rất tiếc chúng tôi không thể đến vào ngày đó.', 'Part 5', 'Vocabulary', 'Câu 124 · Đáp án (A) regrettably: regrettably = đáng tiếc là', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-125', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'In celebration of Ms. Tseng''s promotion, tea and cookies will be served following the meeting.', 'Để chúc mừng bà Tseng được thăng chức, trà và bánh quy sẽ được phục vụ sau cuộc họp.', 'Part 5', 'Preposition', 'Câu 125 · Đáp án (C) following: following = after (giới từ)', 'In celebration of Ms Tseng''s promotion, tea and cookies will be served following the meeting.', NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
