('wn26-04-127', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'The accounting department''s new policy outlines the preferred process for the procurement of office equipment.', 'Chính sách mới của phòng kế toán nêu ra quy trình được ưu tiên cho việc mua sắm thiết bị văn phòng.', 'Part 5', 'Word form', 'Câu 127 · Đáp án (C) preferred: tính từ preferred + danh từ process', NULL, NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-128', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'All documents pertaining to the company merger will become available to the public within one year.', 'Tất cả tài liệu liên quan đến việc sáp nhập công ty sẽ được công khai trong vòng một năm.', 'Part 5', 'Vocabulary', 'Câu 128 · Đáp án (C) pertaining: pertaining to = liên quan đến', NULL, NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-129', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'Granta Hospital has added several pediatric nurses to its staff as part of its new affiliation with the Friel School of Nursing.', 'Bệnh viện Granta đã tuyển thêm một số y tá nhi khoa trong khuôn khổ sự liên kết mới với Trường Điều dưỡng Friel.', 'Part 5', 'Word form', 'Câu 129 · Đáp án (A) affiliation: its + tính từ + danh từ affiliation', NULL, NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-04-130', 'ETS 2026 · Test 04', 'winner-e26-p5-04', 'During checkout, cashiers must be able to scan purchased items accurately as well as field questions from customers.', 'Khi thanh toán, thu ngân phải quét chính xác hàng đã mua cũng như trả lời câu hỏi của khách hàng.', 'Part 5', 'Conjunction', 'Câu 130 · Đáp án (D) as well as: as well as = cũng như; field questions = xử lý câu hỏi', NULL, NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 4, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-101', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Mr. Choi, who recently joined the advisory board, is an experienced accountant and investor.', 'Ông Choi, người vừa gia nhập ban cố vấn, là một kế toán và nhà đầu tư giàu kinh nghiệm.', 'Part 5', 'Conjunction', 'Câu 101 · Đáp án (C) and: and nối hai danh từ ngang hàng', 'Mr Choi, who recently joined the advisory board, is an experienced accountant and investor.', NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-102', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'The first 150 visitors to the new fitness park will each receive a complimentary water bottle.', '150 khách đầu tiên đến công viên thể dục mới sẽ mỗi người nhận một bình nước miễn phí.', 'Part 5', 'Word form', 'Câu 102 · Đáp án (A) bottle: a + tính từ + danh từ ghép water bottle', NULL, NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-103', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Operating instructions for the printer will be e-mailed to employees shortly.', 'Hướng dẫn vận hành máy in sẽ sớm được gửi e-mail cho nhân viên.', 'Part 5', 'Word form', 'Câu 103 · Đáp án (B) shortly: shortly = sớm, chẳng bao lâu nữa (trạng từ)', NULL, NULL, NULL, 3, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-104', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Dozens of satisfied customers have posted positive reviews of Stellenbosch Cycle Works.', 'Hàng chục khách hàng hài lòng đã đăng đánh giá tích cực về Stellenbosch Cycle Works.', 'Part 5', 'Word form', 'Câu 104 · Đáp án (B) satisfied: tính từ V-ed (cảm xúc của người) + danh từ', NULL, NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-105', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Ms. Lim''s best-selling novel has been widely praised.', 'Cuốn tiểu thuyết bán chạy của cô Lim đã được khen ngợi rộng rãi.', 'Part 5', 'Vocabulary', 'Câu 105 · Đáp án (D) widely: widely praised = được khen ngợi rộng rãi', 'Ms Lim''s best-selling novel has been widely praised.', NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-106', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'The marketing manager, Ms. Abyola, plans to meet with the press following her meeting with the vice president.', 'Trưởng phòng tiếp thị, cô Abyola, dự định gặp báo chí sau cuộc gặp của cô ấy với phó chủ tịch.', 'Part 5', 'Pronoun', 'Câu 106 · Đáp án (A) her: tính từ sở hữu her + danh từ meeting', 'The marketing manager, Ms Abyola, plans to meet with the press following her meeting with the vice president.', NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-107', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Last weekend, Terriville Community Center held a lively game night for neighborhood children.', 'Cuối tuần trước, Trung tâm Cộng đồng Terriville đã tổ chức một đêm trò chơi sôi nổi cho trẻ em trong khu phố.', 'Part 5', 'Vocabulary', 'Câu 107 · Đáp án (C) lively: lively = sôi nổi', NULL, NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-108', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Mr. Lenthe will distribute copies of the workshop agenda to all managers by Tuesday morning.', 'Ông Lenthe sẽ phát các bản sao của chương trình hội thảo cho tất cả quản lý trước sáng thứ Ba.', 'Part 5', 'Word form', 'Câu 108 · Đáp án (A) copies: distribute + danh từ copies (bản sao)', 'Mr Lenthe will distribute copies of the workshop agenda to all managers by Tuesday morning.', NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-109', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Employees are eligible for more vacation time after they have been employed for five years.', 'Nhân viên đủ điều kiện nhận thêm ngày nghỉ phép sau khi đã làm việc được năm năm.', 'Part 5', 'Conjunction', 'Câu 109 · Đáp án (A) after: after + mệnh đề = sau khi', NULL, NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-110', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Managers at Afton Accounting are urged to provide constructive feedback to employees on a regular basis.', 'Các quản lý tại Afton Accounting được khuyến khích đưa ra phản hồi mang tính xây dựng cho nhân viên một cách thường xuyên.', 'Part 5', 'Word form', 'Câu 110 · Đáp án (C) constructive: tính từ constructive + danh từ feedback', NULL, NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-111', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Many farmers markets operate on a seasonal basis, opening in spring and closing in late autumn.', 'Nhiều chợ nông sản hoạt động theo mùa, mở cửa vào mùa xuân và đóng cửa vào cuối thu.', 'Part 5', 'Vocabulary', 'Câu 111 · Đáp án (B) basis: on a … basis = theo …', NULL, NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-112', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Weakness in the housing market has continued to drag down real estate profits.', 'Sự yếu kém của thị trường nhà ở tiếp tục kéo giảm lợi nhuận bất động sản.', 'Part 5', 'Word form', 'Câu 112 · Đáp án (C) Weakness: cần danh từ làm chủ ngữ', NULL, NULL, NULL, 12, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-113', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'The sudden merger of Alvy Brothers and Craford Enterprises surprised most financial analysts.', 'Vụ sáp nhập đột ngột giữa Alvy Brothers và Craford Enterprises khiến hầu hết các nhà phân tích tài chính bất ngờ.', 'Part 5', 'Vocabulary', 'Câu 113 · Đáp án (C) surprised: surprise sb = khiến ai bất ngờ', NULL, NULL, NULL, 13, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-114', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Of all the mistakes people make in the office, not proofreading their e-mails is one of the most common.', 'Trong tất cả các lỗi người ta mắc ở văn phòng, không đọc soát e-mail là một trong những lỗi phổ biến nhất.', 'Part 5', 'Word form', 'Câu 114 · Đáp án (B) most common: one of the + so sánh nhất', NULL, NULL, NULL, 14, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-115', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Cayfair Global''s primary mission is to transport and deliver client goods in a timely manner.', 'Sứ mệnh chính của Cayfair Global là vận chuyển và giao hàng cho khách hàng đúng hạn.', 'Part 5', 'Vocabulary', 'Câu 115 · Đáp án (B) primary: primary = chính, hàng đầu', NULL, NULL, NULL, 15, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-116', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'The department supervisor is responsible for ensuring that all safety gear is stowed properly at the end of the shift.', 'Trưởng bộ phận chịu trách nhiệm đảm bảo mọi đồ bảo hộ được cất đúng chỗ vào cuối ca.', 'Part 5', 'Word form', 'Câu 116 · Đáp án (D) responsible: be responsible for = chịu trách nhiệm', NULL, NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-117', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'A three-year project deepened the harbor, allowing it to accommodate the largest cargo ships.', 'Một dự án kéo dài ba năm đã nạo sâu bến cảng, giúp cảng tiếp nhận được những tàu chở hàng lớn nhất.', 'Part 5', 'Vocabulary', 'Câu 117 · Đáp án (C) harbor: harbor = bến cảng (hợp với cargo ships)', NULL, NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-118', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'The experiment''s initial results were wildly different from what was expected.', 'Kết quả ban đầu của thí nghiệm khác biệt hoàn toàn so với dự kiến.', 'Part 5', 'Word form', 'Câu 118 · Đáp án (C) wildly: trạng từ bổ nghĩa cho tính từ different', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-119', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Despite critical reviews, the movie was a great success at the box office.', 'Bất chấp những đánh giá chê bai, bộ phim vẫn thành công lớn về doanh thu phòng vé.', 'Part 5', 'Preposition', 'Câu 119 · Đáp án (C) Despite: Despite + cụm danh từ', NULL, NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-120', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'The spray-on sealant acts as a protective layer that keeps your tiles from getting scratched.', 'Lớp phủ dạng xịt đóng vai trò như một lớp bảo vệ giúp gạch không bị trầy xước.', 'Part 5', 'Verb form', 'Câu 120 · Đáp án (A) acts: câu thiếu động từ chính; chủ ngữ số ít → acts', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-121', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'The contract for the renovation of the park will not be awarded until all bids have been submitted.', 'Hợp đồng cải tạo công viên sẽ không được trao cho đến khi tất cả hồ sơ thầu được nộp.', 'Part 5', 'Conjunction', 'Câu 121 · Đáp án (C) until: not … until = chỉ khi, cho đến khi', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-122', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'A recent study showed that substituting refined sugars with maple syrup may have some important health benefits.', 'Một nghiên cứu gần đây cho thấy thay đường tinh luyện bằng siro phong có thể mang lại một số lợi ích sức khỏe quan trọng.', 'Part 5', 'Vocabulary', 'Câu 122 · Đáp án (D) health: health benefits = lợi ích sức khỏe', NULL, NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-123', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Margie Fung was among the winners at Sternetz Institute''s art competition.', 'Margie Fung nằm trong số những người thắng giải tại cuộc thi nghệ thuật của Viện Sternetz.', 'Part 5', 'Preposition', 'Câu 123 · Đáp án (C) among: among + danh từ số nhiều = trong số', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-124', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Posting updates too infrequently on social media can cause small businesses to be forgotten by their customers.', 'Đăng cập nhật quá thưa thớt trên mạng xã hội có thể khiến các doanh nghiệp nhỏ bị lãng quên bởi chính khách hàng của họ.', 'Part 5', 'Verb form', 'Câu 124 · Đáp án (D) to be forgotten: cause + O + to V; có by → bị động to be V3', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-125', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Ideal for conference rooms, our soundproof panels have been specially designed to absorb unwanted background noise.', 'Lý tưởng cho phòng họp, tấm cách âm của chúng tôi được thiết kế đặc biệt để hấp thụ tiếng ồn xung quanh không mong muốn.', 'Part 5', 'Vocabulary', 'Câu 125 · Đáp án (B) absorb: absorb noise = hấp thụ tiếng ồn', NULL, NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-126', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Mr. Sato will call into the meeting using the hotel''s wireless network.', 'Ông Sato sẽ gọi vào cuộc họp bằng mạng không dây của khách sạn.', 'Part 5', 'Verb form', 'Câu 126 · Đáp án (B) using: V-ing rút gọn = bằng cách sử dụng', 'Mr Sato will call into the meeting using the hotel''s wireless network.', NULL, NULL, 26, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-127', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Not only has Mr. Ogbu diligently worked on the project, but he has also trained Ms. Jeong to continue the work.', 'Ông Ogbu không chỉ làm việc chăm chỉ cho dự án mà còn đào tạo cô Jeong để tiếp tục công việc.', 'Part 5', 'Vocabulary', 'Câu 127 · Đáp án (B) diligently: diligently = chăm chỉ', 'Not only has Mr Ogbu diligently worked on the project, but he has also trained Ms Jeong to continue the work.', NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-128', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Belker Auto offers a ten-year warranty for those who want greater peace of mind.', 'Belker Auto cung cấp bảo hành mười năm cho những ai muốn yên tâm hơn.', 'Part 5', 'Pronoun', 'Câu 128 · Đáp án (B) those: those who = những người mà', NULL, NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-129', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'After months of planning, the Lanton Bookstore school reading program will finally commence in October.', 'Sau nhiều tháng lên kế hoạch, chương trình đọc sách trường học của Lanton Bookstore cuối cùng sẽ bắt đầu vào tháng Mười.', 'Part 5', 'Vocabulary', 'Câu 129 · Đáp án (C) commence: commence = bắt đầu', NULL, NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-05-130', 'ETS 2026 · Test 05', 'winner-e26-p5-05', 'Independent consultants can be a valuable source of impartial advice to new entrepreneurs.', 'Các chuyên gia tư vấn độc lập có thể là nguồn lời khuyên khách quan quý giá cho doanh nhân mới.', 'Part 5', 'Vocabulary', 'Câu 130 · Đáp án (D) impartial: impartial = khách quan, công bằng', NULL, NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 5, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-101', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'On Saturday, the Edbridge Orchestra will perform a new work by local composer Nina Borstein.', 'Vào thứ Bảy, Dàn nhạc Edbridge sẽ biểu diễn một tác phẩm mới của nhà soạn nhạc địa phương Nina Borstein.', 'Part 5', 'Vocabulary', 'Câu 101 · Đáp án (C) perform: perform a work = biểu diễn tác phẩm', NULL, NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-102', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'It is important to be especially polite when in the company of new clients.', 'Điều quan trọng là phải đặc biệt lịch sự khi ở cùng khách hàng mới.', 'Part 5', 'Word form', 'Câu 102 · Đáp án (A) polite: be + (trạng từ) + tính từ', NULL, NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-103', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Although Ms. Endou was not chosen for an award, her achievements were praised.', 'Mặc dù bà Endou không được chọn trao giải, những thành tích của bà được khen ngợi.', 'Part 5', 'Pronoun', 'Câu 103 · Đáp án (B) her: tính từ sở hữu her + danh từ achievements', 'Although Ms Endou was not chosen for an award, her achievements were praised.', NULL, NULL, 3, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-104', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'At the end of the year, organizations face pressure to achieve their financial goals.', 'Vào cuối năm, các tổ chức chịu áp lực phải đạt được mục tiêu tài chính.', 'Part 5', 'Vocabulary', 'Câu 104 · Đáp án (B) goals: achieve goals = đạt mục tiêu', NULL, NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-105', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Online ordering is available on Naito Café''s Web site.', 'Có thể đặt hàng trực tuyến trên trang web của Naito Café.', 'Part 5', 'Vocabulary', 'Câu 105 · Đáp án (D) available: be available = có sẵn, có thể dùng', 'Online ordering is available on Naito Café''s Website.', NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-106', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Mayor Park plans to meet with his campaign staff following the televised debate.', 'Thị trưởng Park dự định gặp đội ngũ vận động tranh cử sau cuộc tranh luận trên truyền hình.', 'Part 5', 'Preposition', 'Câu 106 · Đáp án (A) following: following = after (giới từ)', NULL, NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-107', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Mr. Suh has requested that a more reliable copy machine be purchased for the finance department.', 'Ông Suh đã đề nghị mua một máy photocopy đáng tin cậy hơn cho phòng tài chính.', 'Part 5', 'Word form', 'Câu 107 · Đáp án (D) reliable: more + tính từ + danh từ', 'Mr Suh has requested that a more reliable copy machine be purchased for the finance department.', NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-108', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Mr. Aponte''s photograph of the autumn foliage will be featured on the front cover of Outward Expansion Magazine.', 'Bức ảnh lá mùa thu của ông Aponte sẽ xuất hiện trên trang bìa của tạp chí Outward Expansion.', 'Part 5', 'Word form', 'Câu 108 · Đáp án (A) cover: front cover = trang bìa', 'Mr Aponte''s photograph of the autumn foliage will be featured on the front cover of Outward Expansion Magazine.', NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-109', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Handi Office Supplies'' new desk organizers serve as practical and stylish additions to any office workstation.', 'Kệ sắp xếp bàn làm việc mới của Handi Office Supplies đóng vai trò là vật dụng bổ sung tiện dụng và thời trang cho mọi góc làm việc.', 'Part 5', 'Preposition', 'Câu 109 · Đáp án (B) as: serve as = đóng vai trò là', NULL, NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-110', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'The efficient redesign of the airline terminal led to fewer flight delays.', 'Việc thiết kế lại hiệu quả nhà ga hàng không đã giúp có ít chuyến bay bị hoãn hơn.', 'Part 5', 'Vocabulary', 'Câu 110 · Đáp án (D) fewer: fewer + danh từ đếm được số nhiều', NULL, NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-111', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Mr. Ogbu''s editor appreciated his ability to approach the subject matter objectively.', 'Biên tập viên của ông Ogbu đánh giá cao khả năng tiếp cận chủ đề một cách khách quan của ông.', 'Part 5', 'Word form', 'Câu 111 · Đáp án (C) objectively: trạng từ bổ nghĩa cho động từ approach', 'Mr Ogbu''s editor appreciated his ability to approach the subject matter objectively.', NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
