('wn26-06-116', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Mr. Brighton''s first assignment at Glynn Engineering was in the materials testing group.', 'Nhiệm vụ đầu tiên của ông Brighton tại Glynn Engineering là ở nhóm kiểm định vật liệu.', 'Part 5', 'Word form', 'Câu 116 · Đáp án (D) assignment: sở hữu cách + first + danh từ', 'Mr Brighton''s first assignment at Glynn Engineering was in the materials testing group.', NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-117', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'The installation of new benches throughout Haverford Park will cost roughly €5,000.', 'Việc lắp đặt ghế băng mới khắp công viên Haverford sẽ tốn khoảng 5.000 euro.', 'Part 5', 'Vocabulary', 'Câu 117 · Đáp án (B) roughly: roughly + con số = khoảng', 'The installation of new benches throughout Haverford Park will cost roughly 5,000 euros.|The installation of new benches throughout Haverford Park will cost roughly 5000 euros.', NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-118', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Anyone who is unable to attend the quarterly stakeholder meeting is welcome to appoint a representative.', 'Bất kỳ ai không thể tham dự cuộc họp cổ đông hằng quý đều có thể cử người đại diện.', 'Part 5', 'Pronoun', 'Câu 118 · Đáp án (C) Anyone: anyone who + động từ số ít = bất kỳ ai', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-119', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Singer Maria Stanley revealed today that she is scheduling a world tour.', 'Ca sĩ Maria Stanley hôm nay đã tiết lộ rằng cô đang lên lịch cho chuyến lưu diễn thế giới.', 'Part 5', 'Verb form', 'Câu 119 · Đáp án (B) revealed: câu thiếu động từ chính; today → quá khứ đơn', NULL, NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-120', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Biographer Amber Bowen has been recognized for her distinctive writing style.', 'Nhà viết tiểu sử Amber Bowen được công nhận nhờ phong cách viết độc đáo.', 'Part 5', 'Word form', 'Câu 120 · Đáp án (D) style: cụm danh từ: tính từ + writing + danh từ style', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-121', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'The award-winning stationery created by the artists at Paperi Designs is of exceptional quality.', 'Văn phòng phẩm từng đoạt giải do các nghệ sĩ của Paperi Designs tạo ra có chất lượng vượt trội.', 'Part 5', 'Vocabulary', 'Câu 121 · Đáp án (B) exceptional: of exceptional quality = chất lượng vượt trội', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
