('wn26-06-123', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Commercial property insurance covers the expenses associated with repairing or rebuilding a business property after certain events.', 'Bảo hiểm tài sản thương mại chi trả các chi phí liên quan đến việc sửa chữa hoặc xây dựng lại tài sản kinh doanh sau một số sự cố nhất định.', 'Part 5', 'Vocabulary', 'Câu 123 · Đáp án (A) expenses: cover expenses = chi trả chi phí', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-124', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'The first-aid class usually fills up quickly, so prompt registration is recommended.', 'Lớp sơ cứu thường nhanh kín chỗ, vì vậy nên đăng ký sớm.', 'Part 5', 'Vocabulary', 'Câu 124 · Đáp án (A) registration: fills up quickly → cần đăng ký (registration) sớm', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-06-125', 'ETS 2026 · Test 06', 'winner-e26-p5-06', 'Manufacturing all its products in-house allows Long Bridge Steel Corp. to control every aspect of the production process.', 'Tự sản xuất toàn bộ sản phẩm giúp Long Bridge Steel Corp. kiểm soát mọi khâu của quy trình sản xuất.', 'Part 5', 'Vocabulary', 'Câu 125 · Đáp án (D) control: control every aspect = kiểm soát mọi khía cạnh', NULL, NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 6, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
