('wn26-07-120', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'A lack of clearly defined milestones was likely why the software development project failed.', 'Sự thiếu các mốc tiến độ được xác định rõ ràng có lẽ là lý do dự án phát triển phần mềm thất bại.', 'Part 5', 'Vocabulary', 'Câu 120 · Đáp án (C) lack: a lack of = sự thiếu', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-121', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'Rosemont Department Store employees are said to be very well-informed, personable, and responsive.', 'Nhân viên của Rosemont Department Store được cho là rất am hiểu, dễ mến và nhiệt tình.', 'Part 5', 'Word form', 'Câu 121 · Đáp án (D) personable: chuỗi tính từ ngang hàng → cần tính từ', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-122', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'The security officer at the front gate will instruct delivery drivers as to where to drop off packages.', 'Nhân viên bảo vệ ở cổng trước sẽ hướng dẫn tài xế giao hàng nơi để bỏ kiện hàng.', 'Part 5', 'Vocabulary', 'Câu 122 · Đáp án (B) instruct: instruct sb as to … = hướng dẫn ai về …', NULL, NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-123', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'Although some tickets to the concert are still available, all the best seats have already been taken.', 'Mặc dù vẫn còn một số vé buổi hòa nhạc, tất cả chỗ ngồi đẹp nhất đã được đặt hết.', 'Part 5', 'Conjunction', 'Câu 123 · Đáp án (A) Although: Although + mệnh đề = mặc dù', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-124', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'Visitors must park in the designated parking area or risk having their vehicle towed.', 'Khách phải đỗ xe tại khu vực quy định, nếu không sẽ có nguy cơ bị kéo xe.', 'Part 5', 'Conjunction', 'Câu 124 · Đáp án (A) or: or = nếu không thì', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-125', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'When Ms. Liu was hired, the intention was to train her to work in the chemistry lab.', 'Khi cô Liu được tuyển, dự định là đào tạo cô ấy làm việc trong phòng thí nghiệm hóa học.', 'Part 5', 'Word form', 'Câu 125 · Đáp án (B) intention: the + danh từ làm chủ ngữ', 'When Ms Liu was hired, the intention was to train her to work in the chemistry lab.', NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-126', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'A favorable effect of increased tourism in our city has been rapid growth in the number of hospitality-related jobs.', 'Một tác động tích cực của việc du lịch phát triển ở thành phố chúng ta là số việc làm ngành dịch vụ lưu trú tăng nhanh.', 'Part 5', 'Vocabulary', 'Câu 126 · Đáp án (C) favorable: favorable = có lợi, tích cực', NULL, NULL, NULL, 26, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-127', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'The new payroll system will send an e-mail to employees whenever a manager edits their time sheet.', 'Hệ thống tính lương mới sẽ gửi e-mail cho nhân viên mỗi khi quản lý chỉnh sửa bảng chấm công của họ.', 'Part 5', 'Conjunction', 'Câu 127 · Đáp án (D) whenever: whenever = mỗi khi', NULL, NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-128', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'The order of the speakers has been changed in case Mr. Chen arrives late.', 'Thứ tự diễn giả đã được thay đổi phòng khi ông Chen đến muộn.', 'Part 5', 'Conjunction', 'Câu 128 · Đáp án (D) in case: in case + mệnh đề = phòng khi', 'The order of the speakers has been changed in case Mr Chen arrives late.', NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-129', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'Even though the fuel container can hold up to a maximum of ten liters, the manufacturer recommends putting in only nine.', 'Mặc dù bình nhiên liệu có thể chứa tối đa mười lít, nhà sản xuất khuyên chỉ nên đổ chín lít.', 'Part 5', 'Vocabulary', 'Câu 129 · Đáp án (A) maximum: a maximum of = tối đa', NULL, NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-07-130', 'ETS 2026 · Test 07', 'winner-e26-p5-07', 'Ever since the Unicycle Café opened for business last May, it has been hosting weekly live music events.', 'Kể từ khi Unicycle Café khai trương vào tháng Năm năm ngoái, quán đã liên tục tổ chức các buổi nhạc sống hằng tuần.', 'Part 5', 'Verb form', 'Câu 130 · Đáp án (B) has been hosting: ever since + quá khứ → hiện tại hoàn thành (tiếp diễn)', NULL, NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 7, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-101', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Sydney Fashion Week drew thousands of excited visitors to the city last week.', 'Tuần lễ Thời trang Sydney đã thu hút hàng nghìn du khách háo hức đến thành phố vào tuần trước.', 'Part 5', 'Word form', 'Câu 101 · Đáp án (B) excited: tính từ V-ed (cảm xúc của người) + danh từ', NULL, NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-102', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Ms. Choi was pleased to learn that she is a finalist in the technology competition.', 'Cô Choi rất vui khi biết rằng cô ấy lọt vào vòng chung kết cuộc thi công nghệ.', 'Part 5', 'Pronoun', 'Câu 102 · Đáp án (A) she: cần đại từ chủ ngữ cho động từ is', 'Ms Choi was pleased to learn that she is a finalist in the technology competition.', NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-103', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'All visitors to the factory should use the entrance on the north side of the building.', 'Tất cả khách tham quan nhà máy nên sử dụng lối vào ở phía bắc tòa nhà.', 'Part 5', 'Word form', 'Câu 103 · Đáp án (B) entrance: the + danh từ entrance', NULL, NULL, NULL, 3, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-104', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Unfortunately, we cannot provide an exact time for the delivery of the new laptops.', 'Rất tiếc, chúng tôi không thể cung cấp thời gian chính xác cho việc giao máy tính xách tay mới.', 'Part 5', 'Vocabulary', 'Câu 104 · Đáp án (A) exact: exact time = thời gian chính xác', NULL, NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-105', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Tourists visiting Star Island are asked to respect the privacy of residents.', 'Du khách đến đảo Star được yêu cầu tôn trọng sự riêng tư của cư dân.', 'Part 5', 'Verb form', 'Câu 105 · Đáp án (C) to respect: be asked to + V', NULL, NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-106', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Rivlyn, Inc., has recycled nearly 11 million kilograms of paper waste over the past decade.', 'Rivlyn, Inc. đã tái chế gần 11 triệu kg giấy thải trong thập kỷ qua.', 'Part 5', 'Vocabulary', 'Câu 106 · Đáp án (B) nearly: nearly + con số = gần', NULL, NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-107', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'The new Dorvale 500 exercise machine is significantly heavier and sturdier than the previous model.', 'Máy tập thể dục Dorvale 500 mới nặng và chắc chắn hơn đáng kể so với mẫu trước đó.', 'Part 5', 'Vocabulary', 'Câu 107 · Đáp án (B) model: model = mẫu (sản phẩm)', NULL, NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-108', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Beachside Inn is the perfect place to host an event for your corporate clients.', 'Beachside Inn là nơi hoàn hảo để tổ chức một sự kiện cho khách hàng doanh nghiệp của bạn.', 'Part 5', 'Vocabulary', 'Câu 108 · Đáp án (C) host: host an event = tổ chức sự kiện', NULL, NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-109', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Advancements in cloud computing have transformed the gaming industry in many ways.', 'Những tiến bộ trong điện toán đám mây đã thay đổi ngành công nghiệp trò chơi theo nhiều cách.', 'Part 5', 'Word form', 'Câu 109 · Đáp án (D) Advancements: động từ have → chủ ngữ danh từ số nhiều', NULL, NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-110', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'To provide feedback about your recent dental appointment, please respond to this brief survey.', 'Để gửi phản hồi về buổi hẹn nha khoa gần đây của bạn, vui lòng trả lời khảo sát ngắn này.', 'Part 5', 'Preposition', 'Câu 110 · Đáp án (A) about: feedback about = phản hồi về', NULL, NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-111', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'If your company computer is not completely functional, please call the IT Department at extension 12.', 'Nếu máy tính công ty của bạn không hoạt động hoàn toàn bình thường, vui lòng gọi Phòng CNTT theo số máy lẻ 12.', 'Part 5', 'Word form', 'Câu 111 · Đáp án (C) completely: trạng từ bổ nghĩa cho tính từ functional', NULL, NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-112', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'The addition of electric buses to our current fleet has made commuting much more pleasant.', 'Việc bổ sung xe buýt điện vào đội xe hiện tại đã giúp việc đi lại dễ chịu hơn nhiều.', 'Part 5', 'Vocabulary', 'Câu 112 · Đáp án (B) addition: the addition of A to B = việc bổ sung A vào B', NULL, NULL, NULL, 12, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-113', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'The Zwick Air Wave generates a powerful blast to cool your workspace quickly.', 'Zwick Air Wave tạo ra luồng gió mạnh để làm mát không gian làm việc nhanh chóng.', 'Part 5', 'Word form', 'Câu 113 · Đáp án (D) quickly: trạng từ bổ nghĩa cho động từ cool', NULL, NULL, NULL, 13, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-114', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'The Oak Hill Art Museum offers several permanent exhibits and a series of limited-time exhibits.', 'Bảo tàng Nghệ thuật Oak Hill có một số khu trưng bày thường trực và một loạt triển lãm có thời hạn.', 'Part 5', 'Vocabulary', 'Câu 114 · Đáp án (B) permanent: permanent ↔ limited-time', NULL, NULL, NULL, 14, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-115', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Any remote employees wanting an additional computer monitor should notify Ms. Suzuki.', 'Nhân viên làm việc từ xa nào muốn thêm màn hình máy tính nên thông báo cho cô Suzuki.', 'Part 5', 'Vocabulary', 'Câu 115 · Đáp án (D) notify: notify sb = thông báo cho ai', 'Any remote employees wanting an additional computer monitor should notify Ms Suzuki.', NULL, NULL, 15, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-116', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Customer loyalty programs are profitable for many retail businesses.', 'Chương trình khách hàng thân thiết mang lại lợi nhuận cho nhiều doanh nghiệp bán lẻ.', 'Part 5', 'Word form', 'Câu 116 · Đáp án (B) profitable: be + tính từ profitable', NULL, NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-117', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Prompt submission of travel vouchers to the accounts department will expedite refunds.', 'Việc nộp kịp thời phiếu công tác phí cho phòng kế toán sẽ giúp hoàn tiền nhanh hơn.', 'Part 5', 'Preposition', 'Câu 117 · Đáp án (A) to: submission of sth to sb = nộp cái gì cho ai', NULL, NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-118', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'After extensively reviewing our hiring policies, the consultant recommended a simpler process.', 'Sau khi xem xét kỹ lưỡng chính sách tuyển dụng của chúng tôi, chuyên gia tư vấn đã đề xuất một quy trình đơn giản hơn.', 'Part 5', 'Verb form', 'Câu 118 · Đáp án (C) reviewing: After (giới từ) + V-ing', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-119', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Under the direction of Ms. Kenu, the historical society''s fund-raiser went very well this year.', 'Dưới sự chỉ đạo của bà Kenu, buổi gây quỹ của hội lịch sử năm nay diễn ra rất tốt.', 'Part 5', 'Vocabulary', 'Câu 119 · Đáp án (C) direction: under the direction of = dưới sự chỉ đạo của', 'Under the direction of Ms Kenu, the historical society''s fund-raiser went very well this year.', NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-120', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'The company decided to proceed cautiously with plans to expand into new sales territories.', 'Công ty quyết định tiến hành thận trọng các kế hoạch mở rộng sang khu vực bán hàng mới.', 'Part 5', 'Word form', 'Câu 120 · Đáp án (D) cautiously: trạng từ bổ nghĩa cho động từ proceed', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-121', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'In order to access the building, enter the code listed on the tenant directory.', 'Để vào tòa nhà, hãy nhập mã có trong danh bạ người thuê.', 'Part 5', 'Conjunction', 'Câu 121 · Đáp án (A) In order to: In order to + V = để', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-122', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Mr. Davis from the marketing department will attend Monday''s meeting with the client.', 'Ông Davis của phòng tiếp thị sẽ tham dự cuộc họp với khách hàng vào thứ Hai.', 'Part 5', 'Preposition', 'Câu 122 · Đáp án (D) from: from + bộ phận = đến từ, thuộc', 'Mr Davis from the marketing department will attend Monday''s meeting with the client.', NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-123', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Several outstanding reviews helped make the debut novel a best seller.', 'Nhiều bài đánh giá xuất sắc đã giúp cuốn tiểu thuyết đầu tay trở thành sách bán chạy.', 'Part 5', 'Vocabulary', 'Câu 123 · Đáp án (C) outstanding: outstanding = xuất sắc', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-124', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Please join us in welcoming Dr. Sito, who brings ten years of experience in the aerospace industry to his new position.', 'Xin mời cùng chúng tôi chào đón Tiến sĩ Sito, người mang đến mười năm kinh nghiệm trong ngành hàng không vũ trụ cho vị trí mới.', 'Part 5', 'Verb form', 'Câu 124 · Đáp án (A) join: Please + V nguyên mẫu (câu mệnh lệnh)', 'Please join us in welcoming Dr Sito, who brings ten years of experience in the aerospace industry to his new position.', NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-125', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'A survey of new car buyers asked them to rank features in order from most to least important.', 'Một khảo sát dành cho người mua xe mới yêu cầu họ xếp hạng các tính năng theo thứ tự từ quan trọng nhất đến ít quan trọng nhất.', 'Part 5', 'Vocabulary', 'Câu 125 · Đáp án (C) rank: rank = xếp hạng', NULL, NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-126', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'As head of the Poels Museum, Mr. Ahuja oversaw the acquisition of several significant works of art.', 'Với vai trò giám đốc Bảo tàng Poels, ông Ahuja đã giám sát việc mua lại nhiều tác phẩm nghệ thuật quan trọng.', 'Part 5', 'Word form', 'Câu 126 · Đáp án (C) acquisition: the + danh từ + of', 'As head of the Poels Museum, Mr Ahuja oversaw the acquisition of several significant works of art.', NULL, NULL, 26, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-127', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Later today, we will hold a meeting to discuss changes to protocols before they go into effect next month.', 'Cuối ngày hôm nay, chúng ta sẽ họp để thảo luận các thay đổi về quy trình trước khi chúng có hiệu lực vào tháng sau.', 'Part 5', 'Conjunction', 'Câu 127 · Đáp án (D) before: before + mệnh đề = trước khi', NULL, NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-128', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Customer service representatives can be reached by calling 800-555-0121 between 8:00 A.M. and 4:00 P.M.', 'Nhân viên chăm sóc khách hàng có thể được liên hệ bằng cách gọi số 800-555-0121 từ 8 giờ sáng đến 4 giờ chiều.', 'Part 5', 'Preposition', 'Câu 128 · Đáp án (A) by: by + V-ing = bằng cách', 'Customer service representatives can be reached by calling 800-555-0121 between 8:00 AM and 4:00 PM', NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-129', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'Collaboration between multiple agencies is often challenging, but our project-based consulting can simplify the process for you.', 'Việc hợp tác giữa nhiều cơ quan thường đầy thách thức, nhưng dịch vụ tư vấn theo dự án của chúng tôi có thể đơn giản hóa quy trình cho bạn.', 'Part 5', 'Vocabulary', 'Câu 129 · Đáp án (B) often: often = thường', NULL, NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-08-130', 'ETS 2026 · Test 08', 'winner-e26-p5-08', 'The desserts we had at Giovanni''s Bistro were not as delicious as those we enjoyed at Monteverdi''s Taverna.', 'Các món tráng miệng ở Giovanni''s Bistro không ngon bằng những món chúng tôi đã thưởng thức ở Monteverdi''s Taverna.', 'Part 5', 'Pronoun', 'Câu 130 · Đáp án (B) those: those thay cho danh từ số nhiều desserts', NULL, NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 8, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-101', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Our records indicate that your company car is due for regular service next month.', 'Hồ sơ của chúng tôi cho thấy xe công ty của bạn cần được bảo dưỡng định kỳ vào tháng sau.', 'Part 5', 'Word form', 'Câu 101 · Đáp án (A) records: our + danh từ số nhiều records làm chủ ngữ', NULL, NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-102', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'The main entrance to our office building will be closed on Tuesday because of construction.', 'Lối vào chính của tòa nhà văn phòng chúng tôi sẽ đóng vào thứ Ba do việc xây dựng.', 'Part 5', 'Vocabulary', 'Câu 102 · Đáp án (B) main: main entrance = lối vào chính', NULL, NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-103', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Any document marked "Confidential" must be handled and stored carefully.', 'Bất kỳ tài liệu nào được đánh dấu "Confidential" phải được xử lý và lưu trữ cẩn thận.', 'Part 5', 'Word form', 'Câu 103 · Đáp án (B) carefully: trạng từ carefully bổ nghĩa cho các động từ handled and stored', NULL, NULL, NULL, 3, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-104', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'The new technology allows trains to switch quickly between electric and diesel modes.', 'Công nghệ mới cho phép tàu chuyển đổi nhanh chóng giữa chế độ điện và diesel.', 'Part 5', 'Vocabulary', 'Câu 104 · Đáp án (C) allows: allow + O + to V = cho phép ai/cái gì làm gì', NULL, NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-105', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'The Chocobonne Corporation says it plans to open 28 new stores in the next three years.', 'Tập đoàn Chocobonne cho biết họ dự định mở thêm 28 cửa hàng mới trong ba năm tới.', 'Part 5', 'Word form', 'Câu 105 · Đáp án (A) stores: số đếm 28 + danh từ số nhiều stores', NULL, NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-106', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'The Lofstrom Shopping Center is seeking new tenants to rent vacant retail space.', 'Trung tâm mua sắm Lofstrom đang tìm kiếm khách thuê mới để thuê không gian bán lẻ còn trống.', 'Part 5', 'Vocabulary', 'Câu 106 · Đáp án (A) seeking: seek new tenants = tìm kiếm khách thuê mới', NULL, NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-107', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'The painter Marion Settimi developed her distinctive style during the years she lived in Indonesia.', 'Họa sĩ Marion Settimi đã phát triển phong cách đặc trưng của mình trong những năm bà sống ở Indonesia.', 'Part 5', 'Pronoun', 'Câu 107 · Đáp án (C) her: tính từ sở hữu her + danh từ style', NULL, NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-108', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'The company picnic at Floral Park will begin at noon on Saturday and end around 4:00 P.M.', 'Buổi dã ngoại của công ty tại Floral Park sẽ bắt đầu vào giữa trưa thứ Bảy và kết thúc vào khoảng 4 giờ chiều.', 'Part 5', 'Preposition', 'Câu 108 · Đáp án (A) around: end around + giờ = kết thúc vào khoảng', 'The company picnic at Floral Park will begin at noon on Saturday and end around 4:00 PM', NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-109', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Last Monday, the department celebrated Mr. Okada''s recent promotion to manager.', 'Thứ Hai tuần trước, phòng đã tổ chức ăn mừng việc ông Okada mới được thăng chức quản lý.', 'Part 5', 'Verb form', 'Câu 109 · Đáp án (B) celebrated: Last Monday → thì quá khứ đơn celebrated', 'Last Monday, the department celebrated Mr Okada''s recent promotion to manager.', NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-110', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Ms. Xuan''s proposal for reducing the company''s energy consumption is worth considering.', 'Đề xuất của cô Xuân về việc giảm tiêu thụ năng lượng của công ty đáng được xem xét.', 'Part 5', 'Vocabulary', 'Câu 110 · Đáp án (D) proposal: proposal for + V-ing = đề xuất về việc', 'Ms Xuan''s proposal for reducing the company''s energy consumption is worth considering.', NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-111', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Dr. Grayston enthusiastically accepted the position of school superintendent.', 'Tiến sĩ Grayston đã hào hứng nhận vị trí giám đốc học vụ.', 'Part 5', 'Word form', 'Câu 111 · Đáp án (C) enthusiastically: trạng từ enthusiastically bổ nghĩa cho động từ accepted', 'Dr Grayston enthusiastically accepted the position of school superintendent.', NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-112', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Austina Gallery is located at the northern end of Arch Street, opposite the Verdigris Bistro.', 'Phòng trưng bày Austina nằm ở đầu phía bắc phố Arch, đối diện với nhà hàng Verdigris Bistro.', 'Part 5', 'Preposition', 'Câu 112 · Đáp án (A) opposite: opposite = đối diện (giới từ, không cần "to")', NULL, NULL, NULL, 12, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-113', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Mr. Garcia promised to become a mentor to Ms. Winston after he retired.', 'Ông Garcia đã hứa sẽ trở thành người cố vấn cho cô Winston sau khi ông nghỉ hưu.', 'Part 5', 'Verb form', 'Câu 113 · Đáp án (C) to become: promise + to V', 'Mr Garcia promised to become a mentor to Ms Winston after he retired.', NULL, NULL, 13, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-114', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Once considered a specialty product, shoes made from recycled materials are now widely available.', 'Từng được coi là sản phẩm đặc thù, giày làm từ vật liệu tái chế hiện nay đã có bán rộng rãi.', 'Part 5', 'Vocabulary', 'Câu 114 · Đáp án (B) widely: widely available = có bán rộng rãi', NULL, NULL, NULL, 14, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-115', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Yuping University has formed partnerships with local businesses to create internship opportunities for its students.', 'Đại học Yuping đã thiết lập các mối quan hệ hợp tác với doanh nghiệp địa phương để tạo cơ hội thực tập cho sinh viên.', 'Part 5', 'Word form', 'Câu 115 · Đáp án (D) partnerships: form partnerships = thiết lập quan hệ hợp tác', NULL, NULL, NULL, 15, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-116', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Our market research shows that buyers with limited knowledge of a product often look for information from expert sources.', 'Nghiên cứu thị trường của chúng tôi cho thấy người mua có ít hiểu biết về sản phẩm thường tìm thông tin từ các nguồn chuyên gia.', 'Part 5', 'Vocabulary', 'Câu 116 · Đáp án (A) knowledge: limited knowledge of = hiểu biết hạn chế về', NULL, NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-117', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Something is preventing the graphic artists from accessing the image files in the main database.', 'Có điều gì đó đang khiến các họa sĩ đồ họa không thể truy cập các tập tin hình ảnh trong cơ sở dữ liệu chính.', 'Part 5', 'Pronoun', 'Câu 117 · Đáp án (C) Something: Something + động từ số ít is preventing; đại từ không xác định làm chủ ngữ', NULL, NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-118', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Despite a delay, Thaintech completed the renovation of its warehouse before the target date of April 7.', 'Mặc dù bị chậm trễ, Thaintech đã hoàn thành việc cải tạo nhà kho trước ngày mục tiêu 7 tháng 4.', 'Part 5', 'Conjunction', 'Câu 118 · Đáp án (B) Despite: Despite + cụm danh từ (a delay)', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-119', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'While its credit card system is offline, the Lexler Department Store is effectively closed for business.', 'Trong khi hệ thống thẻ tín dụng ngừng hoạt động, cửa hàng bách hóa Lexler thực chất đã ngừng kinh doanh.', 'Part 5', 'Word form', 'Câu 119 · Đáp án (D) effectively: trạng từ effectively bổ nghĩa cho tính từ closed', NULL, NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-120', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Nearly half of the toy manufacturers surveyed reported increased sales over the last two years.', 'Gần một nửa số nhà sản xuất đồ chơi được khảo sát báo cáo doanh số tăng trong hai năm qua.', 'Part 5', 'Preposition', 'Câu 120 · Đáp án (D) over: over the last two years = trong hai năm qua', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-121', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Nonprofit groups may submit up to three applications for funding consideration during any given calendar year.', 'Các tổ chức phi lợi nhuận có thể nộp tối đa ba đơn xin xét cấp kinh phí trong bất kỳ năm dương lịch nào.', 'Part 5', 'Verb form', 'Câu 121 · Đáp án (D) may submit: chủ ngữ số nhiều groups + động từ khiếm khuyết may + V nguyên mẫu submit', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-122', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Critics reacted favorably to the new musical, praising the exciting design and impressive choreography.', 'Các nhà phê bình đã phản ứng tích cực với vở nhạc kịch mới, khen ngợi phần thiết kế sôi động và biên đạo múa ấn tượng.', 'Part 5', 'Vocabulary', 'Câu 122 · Đáp án (B) favorably: react favorably to = phản ứng tích cực với', NULL, NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-123', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Clausen''s Notes is well-known among writers and publishers for its in-depth reviews of books.', 'Clausen''s Notes được biết đến rộng rãi trong giới nhà văn và nhà xuất bản nhờ các bài đánh giá sách sâu sắc.', 'Part 5', 'Preposition', 'Câu 123 · Đáp án (C) among: well-known among = được biết đến trong (số nhiều)', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-124', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'The ongoing shortage of hardwood has caused the price of certain furniture items to soar.', 'Tình trạng thiếu gỗ cứng kéo dài đã khiến giá của một số mặt hàng nội thất tăng vọt.', 'Part 5', 'Vocabulary', 'Câu 124 · Đáp án (C) soar: soar = tăng vọt (giá cả)', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-125', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Attach the magnetic tray to any flat steel surface for easy storage of and access to household or automotive tools.', 'Gắn khay từ tính lên bất kỳ mặt phẳng bằng thép nào để dễ dàng cất giữ và lấy dụng cụ gia đình hoặc ô tô.', 'Part 5', 'Word form', 'Câu 125 · Đáp án (A) magnetic: tính từ magnetic + danh từ tray', NULL, NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-126', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'The customer neglected to buy an extended warranty on the dishwasher, so it is not eligible for a free repair.', 'Khách hàng đã sơ suất không mua bảo hành mở rộng cho máy rửa bát, vì vậy máy không đủ điều kiện sửa miễn phí.', 'Part 5', 'Vocabulary', 'Câu 126 · Đáp án (B) neglected: neglect to V = sơ suất/quên không làm gì', NULL, NULL, NULL, 26, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-127', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Although much of the material was technical in nature, the audience appeared to remain engaged throughout Ms. Sharma''s presentation.', 'Mặc dù phần lớn nội dung mang tính kỹ thuật, khán giả vẫn có vẻ tập trung theo dõi suốt buổi thuyết trình của cô Sharma.', 'Part 5', 'Word form', 'Câu 127 · Đáp án (B) engaged: remain + tính từ V-ed (engaged) = vẫn ở trạng thái tập trung, hào hứng', 'Although much of the material was technical in nature, the audience appeared to remain engaged throughout Ms Sharma''s presentation.', NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-128', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'In addition to fresh fruit and vegetables, vendors at the Wattville Farm Market also sell various handmade goods.', 'Ngoài rau củ quả tươi, các gian hàng tại chợ nông sản Wattville còn bán nhiều mặt hàng thủ công.', 'Part 5', 'Conjunction', 'Câu 128 · Đáp án (B) In addition to: In addition to = ngoài ra, bên cạnh (giới từ cụm mở đầu câu)', NULL, NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-129', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'Whichever route they choose, it should take the management team approximately four hours to drive to the hotel in Antibes.', 'Dù họ chọn tuyến đường nào, đội ngũ quản lý cũng sẽ mất khoảng bốn giờ lái xe đến khách sạn ở Antibes.', 'Part 5', 'Pronoun', 'Câu 129 · Đáp án (D) Whichever: Whichever + danh từ = dù là ... nào', NULL, NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-09-130', 'ETS 2026 · Test 09', 'winner-e26-p5-09', 'All Baraantec Ltd. hand tools undergo rigorous inspections to ensure they are free of defects.', 'Tất cả dụng cụ cầm tay của Baraantec Ltd. đều trải qua các cuộc kiểm tra nghiêm ngặt để đảm bảo không có lỗi.', 'Part 5', 'Vocabulary', 'Câu 130 · Đáp án (A) rigorous: rigorous inspections = kiểm tra nghiêm ngặt', NULL, NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 9, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-101', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Sophia Hollinger was commended for her work on the Kala account.', 'Sophia Hollinger được khen ngợi vì công việc của cô ấy với khách hàng Kala.', 'Part 5', 'Pronoun', 'Câu 101 · Đáp án (A) her: tính từ sở hữu her + danh từ work', NULL, NULL, NULL, 1, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-102', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Last summer, jazz musician Jay Deswani performed on the main concert stage at Waterfront Park.', 'Mùa hè năm ngoái, nhạc sĩ jazz Jay Deswani đã biểu diễn trên sân khấu chính tại công viên Waterfront.', 'Part 5', 'Vocabulary', 'Câu 102 · Đáp án (D) performed: musician + stage → perform', NULL, NULL, NULL, 2, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-103', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'The purchasing department ordered six additional cases of ink toner.', 'Phòng mua hàng đã đặt thêm sáu thùng mực in.', 'Part 5', 'Word form', 'Câu 103 · Đáp án (B) additional: tính từ additional + danh từ cases', NULL, NULL, NULL, 3, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-104', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Please complete the questionnaire to help our team better understand the financial services you are interested in.', 'Vui lòng hoàn thành bảng câu hỏi để giúp đội ngũ của chúng tôi hiểu rõ hơn các dịch vụ tài chính mà bạn quan tâm.', 'Part 5', 'Vocabulary', 'Câu 104 · Đáp án (A) better: better understand = hiểu rõ hơn', NULL, NULL, NULL, 4, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-105', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Production of the garments will begin two weeks after the contract is signed.', 'Việc sản xuất quần áo sẽ bắt đầu hai tuần sau khi hợp đồng được ký.', 'Part 5', 'Word form', 'Câu 105 · Đáp án (D) Production: danh từ làm chủ ngữ + of', NULL, NULL, NULL, 5, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-106', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'The minutes of last week''s board meeting had only three minor errors.', 'Biên bản cuộc họp hội đồng tuần trước chỉ có ba lỗi nhỏ.', 'Part 5', 'Vocabulary', 'Câu 106 · Đáp án (B) minor: minor errors = lỗi nhỏ', NULL, NULL, NULL, 6, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-107', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Patrons are asked to silence their phones when the show begins.', 'Khán giả được yêu cầu tắt chuông điện thoại khi buổi diễn bắt đầu.', 'Part 5', 'Conjunction', 'Câu 107 · Đáp án (A) when: when + mệnh đề thời gian', NULL, NULL, NULL, 7, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-108', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'The majority of the company''s employees commute to work by train.', 'Phần lớn nhân viên công ty đi làm bằng tàu hỏa.', 'Part 5', 'Preposition', 'Câu 108 · Đáp án (B) by: by + phương tiện (không mạo từ)', NULL, NULL, NULL, 8, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-109', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Line 73 is the oldest continuously operating bus line in Raymo City''s history.', 'Tuyến 73 là tuyến xe buýt hoạt động liên tục lâu đời nhất trong lịch sử thành phố Raymo.', 'Part 5', 'Word form', 'Câu 109 · Đáp án (D) continuously: trạng từ bổ nghĩa cho tính từ operating', NULL, NULL, NULL, 9, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-110', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'This message is a reminder to pick up your package at your local post office as soon as possible.', 'Tin nhắn này là lời nhắc đến nhận bưu kiện tại bưu điện địa phương càng sớm càng tốt.', 'Part 5', 'Vocabulary', 'Câu 110 · Đáp án (B) reminder: reminder = lời nhắc', NULL, NULL, NULL, 10, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-111', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Pet Orbit customers who want receipts delivered by e-mail can opt for this service.', 'Khách hàng của Pet Orbit muốn nhận hóa đơn qua e-mail có thể chọn dịch vụ này.', 'Part 5', 'Pronoun', 'Câu 111 · Đáp án (B) who: đại từ quan hệ who thay cho customers', NULL, NULL, NULL, 11, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-112', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Mr. Takajian may be an entry-level employee, but he does not hesitate to take initiative.', 'Anh Takajian có thể chỉ là nhân viên mới vào nghề, nhưng anh ấy không ngần ngại chủ động.', 'Part 5', 'Conjunction', 'Câu 112 · Đáp án (A) but: but nối hai mệnh đề đối lập', 'Mr Takajian may be an entry-level employee, but he does not hesitate to take initiative.', NULL, NULL, 12, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-113', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Carter Department Store allows customers to place items on hold for up to 24 hours.', 'Cửa hàng bách hóa Carter cho phép khách hàng giữ hàng tối đa 24 giờ.', 'Part 5', 'Verb form', 'Câu 113 · Đáp án (B) to place: allow + O + to V', NULL, NULL, NULL, 13, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-114', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Using unique colors and styles, the decor experts at Mamie''s Interiors bring a fashionable look to homes.', 'Sử dụng màu sắc và phong cách độc đáo, các chuyên gia trang trí của Mamie''s Interiors mang đến một diện mạo thời thượng cho ngôi nhà.', 'Part 5', 'Vocabulary', 'Câu 114 · Đáp án (D) fashionable: fashionable = hợp thời trang', NULL, NULL, NULL, 14, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-115', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Because of efficient project management, Sparksware''s latest software program was released on time.', 'Nhờ quản lý dự án hiệu quả, chương trình phần mềm mới nhất của Sparksware được phát hành đúng hạn.', 'Part 5', 'Preposition', 'Câu 115 · Đáp án (C) Because of: Because of + cụm danh từ', NULL, NULL, NULL, 15, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-116', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'The summer line of outdoor furniture will be available at select stores as early as February.', 'Dòng nội thất ngoài trời mùa hè sẽ có bán tại một số cửa hàng chọn lọc sớm nhất từ tháng Hai.', 'Part 5', 'Preposition', 'Câu 116 · Đáp án (B) at: available at + cửa hàng', NULL, NULL, NULL, 16, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-117', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'There has been a noticeable decrease in requests for customer support this quarter.', 'Quý này đã có sự sụt giảm đáng kể về số yêu cầu hỗ trợ khách hàng.', 'Part 5', 'Word form', 'Câu 117 · Đáp án (C) noticeable: a + tính từ + danh từ decrease', NULL, NULL, NULL, 17, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-118', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Bina Dal always wanted to become a diplomat, so she studied international relations at university.', 'Bina Dal luôn muốn trở thành nhà ngoại giao, vì vậy cô ấy đã học quan hệ quốc tế ở đại học.', 'Part 5', 'Conjunction', 'Câu 118 · Đáp án (A) so: so + mệnh đề kết quả = vì vậy', NULL, NULL, NULL, 18, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-119', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Thank you for responding promptly with information about the T-Max 400 printer and scanner.', 'Cảm ơn bạn đã phản hồi nhanh chóng với thông tin về máy in và máy quét T-Max 400.', 'Part 5', 'Word form', 'Câu 119 · Đáp án (B) promptly: trạng từ bổ nghĩa cho động từ responding', NULL, NULL, NULL, 19, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-120', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Owing to the weather, we need to reschedule your appointment for tree removal service.', 'Do thời tiết, chúng tôi cần dời lịch hẹn của bạn cho dịch vụ đốn cây.', 'Part 5', 'Vocabulary', 'Câu 120 · Đáp án (A) reschedule: reschedule = dời lịch', NULL, NULL, NULL, 20, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-121', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'It will require a coordinated effort between the two countries to complete the railway line.', 'Cần có một nỗ lực phối hợp giữa hai quốc gia để hoàn thành tuyến đường sắt.', 'Part 5', 'Word form', 'Câu 121 · Đáp án (C) coordinated: tính từ V-ed + danh từ effort', NULL, NULL, NULL, 21, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-122', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'According to the restaurant''s policy, guests must wait to be seated by the front-of-house staff.', 'Theo chính sách của nhà hàng, khách phải chờ nhân viên tiếp đón xếp chỗ ngồi.', 'Part 5', 'Vocabulary', 'Câu 122 · Đáp án (D) policy: according to the policy = theo chính sách', NULL, NULL, NULL, 22, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-123', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Tickets for Saturday''s football game sold out on Thursday, much sooner than organizers had anticipated.', 'Vé trận bóng đá thứ Bảy đã bán hết vào thứ Năm, sớm hơn nhiều so với dự đoán của ban tổ chức.', 'Part 5', 'Verb form', 'Câu 123 · Đáp án (B) had anticipated: dự đoán xảy ra trước việc bán hết → quá khứ hoàn thành', NULL, NULL, NULL, 23, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-124', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Renewing your auto registration online rather than at the motor vehicle office will save you time.', 'Gia hạn đăng ký xe trực tuyến thay vì tại văn phòng quản lý phương tiện sẽ giúp bạn tiết kiệm thời gian.', 'Part 5', 'Conjunction', 'Câu 124 · Đáp án (D) rather than: rather than = thay vì', NULL, NULL, NULL, 24, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-125', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Given Latoya Model Management''s sound reputation, aspiring models can expect a flourishing career.', 'Xét đến danh tiếng vững chắc của Latoya Model Management, những người mẫu đầy tham vọng có thể kỳ vọng một sự nghiệp thăng hoa.', 'Part 5', 'Preposition', 'Câu 125 · Đáp án (A) Given: Given + cụm danh từ = xét đến', NULL, NULL, NULL, 25, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-126', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Employees are asked to update their contact information so that the staff directory can be finalized.', 'Nhân viên được yêu cầu cập nhật thông tin liên hệ để danh bạ nhân viên có thể được hoàn thiện.', 'Part 5', 'Conjunction', 'Câu 126 · Đáp án (A) so that: so that + S + can = để', NULL, NULL, NULL, 26, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-127', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Glistonford Manufacturing cautions consumers not to buy inferior imitations of its adjustable desks.', 'Glistonford Manufacturing cảnh báo người tiêu dùng không mua hàng nhái kém chất lượng của các mẫu bàn điều chỉnh do hãng sản xuất.', 'Part 5', 'Word form', 'Câu 127 · Đáp án (D) imitations: tính từ inferior + danh từ số nhiều', NULL, NULL, NULL, 27, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-128', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Despite the fact that the use of social media is widespread, many people still rely on newspapers for fact-checked information.', 'Mặc dù thực tế là mạng xã hội được sử dụng rộng rãi, nhiều người vẫn dựa vào báo in để có thông tin đã được kiểm chứng.', 'Part 5', 'Preposition', 'Câu 128 · Đáp án (D) Despite: despite the fact that + mệnh đề', NULL, NULL, NULL, 28, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-129', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'Citing energy efficiency and cost reductions, the presenter made several convincing arguments for installing solar panels.', 'Viện dẫn hiệu quả năng lượng và giảm chi phí, người thuyết trình đã đưa ra một số lập luận thuyết phục cho việc lắp tấm pin mặt trời.', 'Part 5', 'Vocabulary', 'Câu 129 · Đáp án (C) convincing: convincing argument = lập luận thuyết phục', NULL, NULL, NULL, 29, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP()),
('wn26-10-130', 'ETS 2026 · Test 10', 'winner-e26-p5-10', 'After leaving his official government role, Dr. Beasly was named Director of the Nanboro Youth Farming Program.', 'Sau khi rời vị trí chính thức trong chính phủ, Tiến sĩ Beasly được bổ nhiệm làm Giám đốc Chương trình Nông nghiệp Thanh niên Nanboro.', 'Part 5', 'Vocabulary', 'Câu 130 · Đáp án (B) named: be named + chức danh = được bổ nhiệm làm', 'After leaving his official government role, Dr Beasly was named Director of the Nanboro Youth Farming Program.', NULL, NULL, 30, 'toeic-winner', 'TOEIC Winner', 3, 10, UTC_TIMESTAMP(), UTC_TIMESTAMP());
